// Running balances and suggested settle-up payments for a group.

export interface BalanceBill {
  payerId: string;
  totalCents: number;
  shares: { memberId: string; totalCents: number }[];
}
export interface BalanceSettleUp {
  fromId: string;
  toId: string;
  amountCents: number;
}
export interface Payment {
  fromId: string;
  toId: string;
  amountCents: number;
}

/**
 * Net balance per member: positive = is owed, negative = owes.
 * The payer is credited the grand total and every participant is debited their
 * share. A settle-up where A pays B credits A and debits B.
 */
export function computeBalances(
  memberIds: string[],
  bills: BalanceBill[],
  settleUps: BalanceSettleUp[],
): Map<string, number> {
  const balances = new Map(memberIds.map((id) => [id, 0]));
  const add = (id: string, cents: number) => balances.set(id, (balances.get(id) ?? 0) + cents);
  for (const bill of bills) {
    add(bill.payerId, bill.totalCents);
    for (const share of bill.shares) add(share.memberId, -share.totalCents);
  }
  for (const s of settleUps) {
    add(s.fromId, s.amountCents);
    add(s.toId, -s.amountCents);
  }
  return balances;
}

/**
 * Fewest-payments suggestion: repeatedly match the largest debtor with the
 * largest creditor. Ties go to the member listed first.
 */
export function suggestPayments(balances: { memberId: string; cents: number }[]): Payment[] {
  const order = new Map(balances.map((b, i) => [b.memberId, i]));
  const debtors = balances.filter((b) => b.cents < 0).map((b) => ({ id: b.memberId, left: -b.cents }));
  const creditors = balances.filter((b) => b.cents > 0).map((b) => ({ id: b.memberId, left: b.cents }));
  const byLargest = (a: { id: string; left: number }, b: { id: string; left: number }) =>
    b.left - a.left || (order.get(a.id) as number) - (order.get(b.id) as number);
  const payments: Payment[] = [];
  for (;;) {
    debtors.sort(byLargest);
    creditors.sort(byLargest);
    const d = debtors[0];
    const c = creditors[0];
    if (!d || !c || d.left === 0 || c.left === 0) break;
    const amountCents = Math.min(d.left, c.left);
    payments.push({ fromId: d.id, toId: c.id, amountCents });
    d.left -= amountCents;
    c.left -= amountCents;
    if (d.left === 0) debtors.shift();
    if (c.left === 0) creditors.shift();
  }
  return payments;
}

