          RAISE EXCEPTION 'simulated failure';
        END IF;
        RETURN NEW;
      END $$`);
    await pool.query(`CREATE TRIGGER ${fn} BEFORE INSERT ON solo_bill_items FOR EACH ROW EXECUTE FUNCTION ${fn}()`);
