      expect(res.status).toBe(500);
      expect((await agent.get('/api/solo-bills')).body.bills).toEqual([]);
    } finally {
      await pool.query(`DROP TRIGGER ${fn} ON solo_bill_items; DROP FUNCTION ${fn}()`);
    }
  });
});

