// Talking to the server. Every failure becomes an ApiError with a message
// that can be shown to the user as it is.

import { MESSAGES } from '../shared/rules.js';

export class ApiError extends Error {
  constructor(
    public status: number,
    message: string,
    public fields: Record<string, string> = {},
    public code?: string,
  ) {
    super(message);
  }
  /** The server couldn't be reached at all. */
  get offline(): boolean {
    return this.status === 0;
  }
}

type Listener = () => void;
const loggedOutListeners = new Set<Listener>();

/** Called when the server says the session has ended. */
export function onLoggedOut(listener: Listener): () => void {
  loggedOutListeners.add(listener);
  return () => loggedOutListeners.delete(listener);
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  let res: Response;
  try {
    res = await fetch(`/api${path}`, {
      method,
      credentials: 'same-origin',
      headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch {
    throw new ApiError(0, MESSAGES.offline);
  }
  let data: unknown = null;
  try {
    data = await res.json();
  } catch {
    data = null;
  }
  if (!res.ok) {
    const err = (data as { error?: { message?: string; fields?: Record<string, string>; code?: string } } | null)?.error;
    if (res.status === 401 && err?.code === 'NOT_LOGGED_IN') loggedOutListeners.forEach((l) => l());
    const message =
      err?.message ?? (res.status >= 500 ? MESSAGES.offline : 'Something went wrong. Please try again.');
    throw new ApiError(res.status, message, err?.fields ?? {}, err?.code);
  }
  return data as T;
}

export const api = {
  get: <T>(path: string) => request<T>('GET', path),
  post: <T>(path: string, body: unknown = {}) => request<T>('POST', path, body),
  put: <T>(path: string, body: unknown = {}) => request<T>('PUT', path, body),
  del: <T>(path: string) => request<T>('DELETE', path),
};

import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import type { Account, Theme } from '../shared/api.js';
import { api, onLoggedOut } from './api.js';

interface SessionValue {
  /** undefined while checking, null when logged out. */
  account: Account | null | undefined;
  setAccount: (account: Account | null) => void;
  setTheme: (theme: Theme) => Promise<void>;
  logout: () => Promise<void>;
}

const SessionContext = createContext<SessionValue | null>(null);

/** Applies the appearance: "device" follows the device's light/dark setting. */
export function applyTheme(theme: Theme | undefined): void {
  const root = document.documentElement;
  if (!theme || theme === 'device') root.removeAttribute('data-theme');
  else root.setAttribute('data-theme', theme);
}

export function SessionProvider({ children }: { children: ReactNode }) {
  const [account, setAccountState] = useState<Account | null | undefined>(undefined);

  const setAccount = useCallback((next: Account | null) => {
    setAccountState(next);
    applyTheme(next?.theme);
  }, []);

  useEffect(() => {
    let alive = true;
    api
      .get<{ account: Account }>('/me')
      .then((r) => alive && setAccount(r.account))
      .catch(() => alive && setAccount(null));
    const off = onLoggedOut(() => setAccount(null));
    return () => {
      alive = false;
      off();
    };
  }, [setAccount]);

  const setTheme = useCallback(
    async (theme: Theme) => {
      const r = await api.put<{ account: Account }>('/me/theme', { theme });
      setAccount(r.account);
    },
    [setAccount],
  );

  const logout = useCallback(async () => {
    await api.post('/auth/logout').catch(() => {});
    setAccount(null);
  }, [setAccount]);

  const value = useMemo(() => ({ account, setAccount, setTheme, logout }), [account, setAccount, setTheme, logout]);
  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession(): SessionValue {
  const value = useContext(SessionContext);
  if (!value) throw new Error('useSession must be used inside SessionProvider');
  return value;
}

