import { useEffect, useRef, useState } from 'react';
import { NavLink, Navigate, Outlet, useLocation } from 'react-router-dom';
import { useSession } from '../session.js';
import { Skeleton } from './ui.js';

const LINKS = [
  { to: '/', label: 'Dashboard', end: true },
  { to: '/solo', label: 'Solo bills', end: false },
  { to: '/groups', label: 'Groups', end: false },
  { to: '/account', label: 'Account', end: false },
];

function NavLinks({ onNavigate }: { onNavigate?: () => void }) {
  return (
    <ul className="nav-list">
      {LINKS.map((l) => (
        <li key={l.to}>
          <NavLink to={l.to} end={l.end} className="nav-link" onClick={onNavigate}>
            {l.label}
          </NavLink>
        </li>
      ))}
    </ul>
  );
}

/** The logged-in frame: sidebar on wide screens, a menu button on phones. */
export function AppLayout() {
  const { account } = useSession();
  const location = useLocation();
  const [menuOpen, setMenuOpen] = useState(false);
  const mainRef = useRef<HTMLElement>(null);
  const first = useRef(true);

  // After moving to another page, put keyboard focus on its heading.
  useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    const heading = mainRef.current?.querySelector<HTMLElement>('h1');
    heading?.focus();
  }, [location.pathname]);

  if (account === undefined) {
    return (
      <div className="boot">
        <Skeleton lines={4} />
      </div>
    );
  }
  if (account === null) {
    return <Navigate to="/login" replace state={{ from: location.pathname + location.search }} />;
  }

  return (
    <div className="app">
      <a href="#main" className="skip-link">
        Skip to content
      </a>
      <aside className="sidebar">
        <div className="brand">Bill Splitter</div>
        <nav aria-label="Main">
          <NavLinks />
        </nav>
      </aside>
      <header className="topbar">
        <span className="brand">Bill Splitter</span>
        <button
          type="button"
          className="btn btn-secondary menu-button"
          aria-expanded={menuOpen}
          aria-controls="mobile-nav"
          onClick={() => setMenuOpen((o) => !o)}
        >
          Menu
        </button>
      </header>
      {menuOpen && (
        <nav id="mobile-nav" className="mobile-nav" aria-label="Main">
          <NavLinks onNavigate={() => setMenuOpen(false)} />
        </nav>
      )}
      <main id="main" ref={mainRef} className="main" tabIndex={-1}>
        <Outlet />
      </main>
    </div>
  );
}

/** Frame for the login, sign-up and reset pages. */
export function PublicLayout() {
  const { account } = useSession();
  const location = useLocation();
  const from = (location.state as { from?: string } | null)?.from;
  if (account === undefined) {
    return (
      <div className="boot">
        <Skeleton lines={4} />
      </div>
    );
  }
  // The recovery code screen stays visible right after sign-up or reset.
  const showingCode = (location.state as { recoveryCode?: string } | null)?.recoveryCode;
  if (account && !showingCode) return <Navigate to={from ?? '/'} replace />;
  return (
    <main id="main" className="public">
      <div className="public-card">
        <div className="brand brand-large">Bill Splitting Calculator</div>
        <Outlet />
      </div>
    </main>
  );
}

import { useEffect } from 'react';
import { useBlocker } from 'react-router-dom';
import { ConfirmDialog } from './ConfirmDialog.js';

/**
 * Asks before leaving a form with unsaved changes. Links and the back button
 * get our own question; closing or reloading the tab gets the browser's.
 */
export function UnsavedGuard({ dirty }: { dirty: boolean }) {
  const blocker = useBlocker(({ currentLocation, nextLocation }) => dirty && currentLocation.pathname !== nextLocation.pathname);

  useEffect(() => {
    if (!dirty) return;
    const handler = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = '';
    };
    window.addEventListener('beforeunload', handler);
    return () => window.removeEventListener('beforeunload', handler);
  }, [dirty]);

  return (
    <ConfirmDialog
      open={blocker.state === 'blocked'}
      title="You have unsaved changes. Leave without saving?"
      confirmLabel="Leave"
      cancelLabel="Stay"
      danger
      onConfirm={() => blocker.proceed?.()}
      onCancel={() => blocker.reset?.()}
    />
  );
}

import { useEffect, useId, useRef, useState, type KeyboardEvent } from 'react';
import { MESSAGES } from '../../shared/rules.js';

interface Person {
  id: string;
  name: string;
}

interface Props {
  label: string;
  people: Person[];
  selected: string[];
  onChange: (ids: string[]) => void;
  error?: string;
}

/**
 * A dropdown with a tick box per person. Closed, it shows the ticked names.
 * Keyboard: Enter/Space opens, arrow keys move, Space ticks, Esc closes.
 */
export function PeoplePicker({ label, people, selected, onChange, error }: Props) {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const panelId = useId();
  const errorId = useId();
  const names = people.filter((p) => selected.includes(p.id)).map((p) => p.name);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', onDoc);
    const first = wrapRef.current?.querySelector<HTMLInputElement>('input[type=checkbox]');
    first?.focus();
    return () => document.removeEventListener('mousedown', onDoc);
  }, [open]);

  const toggle = (id: string) => {
    onChange(selected.includes(id) ? selected.filter((x) => x !== id) : [...selected, id]);
  };

  const onPanelKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const boxes = Array.from(wrapRef.current?.querySelectorAll<HTMLInputElement>('input[type=checkbox]') ?? []);
    const i = boxes.indexOf(document.activeElement as HTMLInputElement);
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      setOpen(false);
      buttonRef.current?.focus();
    } else if (e.key === 'ArrowDown' && boxes.length) {
      e.preventDefault();
      boxes[(i + 1) % boxes.length].focus();
    } else if (e.key === 'ArrowUp' && boxes.length) {
      e.preventDefault();
      boxes[(i - 1 + boxes.length) % boxes.length].focus();
    }
  };

  return (
    <div className="picker" ref={wrapRef}>
      <button
        ref={buttonRef}
        type="button"
        className={`picker-button${names.length ? '' : ' picker-empty'}`}
        aria-expanded={open}
        aria-controls={panelId}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
        onClick={() => setOpen((o) => !o)}
      >
        <span className="visually-hidden">{label}: </span>
        {names.length ? names.join(', ') : MESSAGES.noSharers}
        <span aria-hidden="true" className="picker-caret">
          ▾
        </span>
      </button>
      {open && (
        <div id={panelId} className="picker-panel" onKeyDown={onPanelKey}>
          <fieldset>
            <legend className="visually-hidden">{label}</legend>
            {people.length === 0 && <p className="muted">Tick who took part first.</p>}
            {people.map((p) => (
              <label key={p.id} className="check">
                <input type="checkbox" checked={selected.includes(p.id)} onChange={() => toggle(p.id)} />
                <span>{p.name}</span>
              </label>
            ))}
          </fieldset>
          <button
            type="button"
            className="btn btn-secondary btn-small"
            onClick={() => {
              setOpen(false);
              buttonRef.current?.focus();
            }}
          >
            Done
          </button>
        </div>
      )}
      {error && (
        <p id={errorId} className="field-error">
          {error}
        </p>
      )}
    </div>
  );
}

// Form state for the bill screens, and the Calculate step (the same checks and
// maths the server uses when saving).

import {
  checkBill,
  checkGroupBill,
  computeGroupBill,
  computeTotals,
  type BillInput,
  type ChargeInput,
  type FieldErrors,
  type GroupBillInput,
  type Share,
  type SplitMode,
  type TipOn,
  type Totals,
} from '../shared/bill.js';
import { CURRENCIES, MAX_ITEMS, MESSAGES, checkCurrency } from '../shared/rules.js';

export interface ItemRow {
  key: number;
  name: string;
  price: string;
  sharerIds: string[];
}

export interface BillFormState {
  name: string;
  items: ItemRow[];
  tax: ChargeInput;
  otherCharges: ChargeInput;
  tip: ChargeInput;
  tipOn: TipOn;
  /** Solo bills: one of the listed symbols, or "other". */
  currencyChoice: string;
  customCurrency: string;
  /** Group bills. */
  splitMode: SplitMode;
  participantIds: string[];
  payerId: string | null;
}

let nextKey = 1;
export const newItem = (over: Partial<ItemRow> = {}): ItemRow => ({ key: nextKey++, name: '', price: '', sharerIds: [], ...over });

export function emptyBill(over: Partial<BillFormState> = {}): BillFormState {
  return {
    name: '',
    items: [newItem()],
    tax: { mode: 'percent', value: '0' },
    otherCharges: { mode: 'amount', value: '' },
    tip: { mode: 'percent', value: '0' },
    tipOn: 'food',
    currencyChoice: '$',
    customCurrency: '',
    splitMode: 'equal',
    participantIds: [],
    payerId: null,
    ...over,
  };
}

/** Rebuilds the form from a saved bill. */
export function fromInput(input: BillInput | GroupBillInput, currency?: string): BillFormState {
  const group = input as Partial<GroupBillInput>;
  const listed = currency !== undefined && (CURRENCIES as readonly string[]).includes(currency);
  return emptyBill({
    name: input.name,
    items: input.items.map((it) => newItem({ name: it.name, price: it.price, sharerIds: it.sharerIds ?? [] })),
    tax: input.tax,
    otherCharges: input.otherCharges,
    tip: input.tip,
    tipOn: input.tipOn,
    currencyChoice: currency === undefined ? '$' : listed ? currency : 'other',
    customCurrency: currency !== undefined && !listed ? currency : '',
    splitMode: group.splitMode ?? 'equal',
    participantIds: group.participantIds ?? [],
    payerId: group.payerId ?? null,
  });
}

export function toBillInput(state: BillFormState): BillInput {
  return {
    name: state.name,
    items: state.items.map((it) => ({ name: it.name, price: it.price })),
    tax: state.tax,
    otherCharges: state.otherCharges,
    tip: state.tip,
    tipOn: state.tipOn,
  };
}

export function toGroupBillInput(state: BillFormState): GroupBillInput {
  return {
    ...toBillInput(state),
    items: state.items.map((it) => ({ name: it.name, price: it.price, sharerIds: it.sharerIds })),
    splitMode: state.splitMode,
    participantIds: state.participantIds,
    payerId: state.payerId,
  };
}

export function chosenCurrency(state: BillFormState): string {
  return state.currencyChoice === 'other' ? state.customCurrency : state.currencyChoice;
}

export interface CalcResult {
  totals: Totals;
  shares: Share[] | null;
}

export type CalcOutcome = { ok: true; result: CalcResult } | { ok: false; errors: FieldErrors };

/** Runs every check; returns the result only when everything is valid. */
export function calculate(state: BillFormState, kind: 'solo' | 'group', checkSoloCurrency: boolean): CalcOutcome {
  if (kind === 'group') {
    const checked = checkGroupBill(toGroupBillInput(state));
    if (!checked.ok) return { ok: false, errors: checked.errors };
    const r = computeGroupBill(checked.value);
    return { ok: true, result: { totals: r.totals, shares: r.shares } };
  }
  const checked = checkBill(toBillInput(state));
  const errors: FieldErrors = checked.ok ? {} : { ...checked.errors };
  if (checkSoloCurrency) {
    const currency = checkCurrency(chosenCurrency(state));
    if (!currency.ok) errors.currency = currency.message;
  }
  if (!checked.ok || Object.keys(errors).length > 0) return { ok: false, errors };
  return { ok: true, result: { totals: computeTotals(checked.value), shares: null } };
}

export function canAddItem(state: BillFormState): boolean {
  return state.items.length < MAX_ITEMS;
}

export const TOO_MANY_ITEMS = MESSAGES.tooManyItems;

/** Moves keyboard focus to the first field with a problem. */
export function focusFirstError(root: HTMLElement | null): void {
  const target = root?.querySelector<HTMLElement>('[aria-invalid="true"], [data-error-anchor]');
  target?.focus();
}

