      { path: '/solo', element: <SoloListPage /> },
      { path: '/solo/new', element: <SoloBillPage /> },
      { path: '/solo/:id', element: <SoloBillPage /> },
      { path: '/groups', element: <GroupsPage /> },
      { path: '/groups/new', element: <NewGroupPage /> },
