        open={confirmDelete}
        title="Delete this payment?"
        confirmLabel="Delete payment"
        danger
        busy={busy}
        onConfirm={() => void onDelete()}
        onCancel={() => setConfirmDelete(false)}
      >
        <p>Balances will be updated. This is recorded in the activity log.</p>
      </ConfirmDialog>
    </>
  );
}

