16	  const res = await page.request.post('/api/auth/signup', { data: { username, password: PASSWORD } });
17	  expect(res.status()).toBe(201);
18	  await page.goto('/');
19	  await expect(page.getByRole('heading', { level: 1, name: 'Dashboard' })).toBeVisible();
20	  return username;
21	}
22	
23	export async function api<T = unknown>(page: Page, method: 'get' | 'post' | 'put' | 'delete', path: string, data?: unknown): Promise<T> {
24	  const body = data === undefined && (method === 'post' || method === 'put') ? {} : data;
25	  const res = await page.request[method](`/api${path}`, body === undefined ? {} : { data: body });
26	  if (!res.ok()) throw new Error(`${method} ${path} -> ${res.status()} ${await res.text()}`);
27	  return (await res.json()) as T;
28	}
29	
30	/** Creates a group with name-only members through the API; returns ids by name. */
31	export async function makeGroup(page: Page, name: string, currency: string, members: string[]) {
32	  const { groupId } = await api<{ groupId: string }>(page, 'post', '/groups', { name, currency });
33	  for (const m of members) await api(page, 'post', `/groups/${groupId}/members`, { name: m });

33	  // US-02 #2-#5: wrong password, then the right one in another letter case.
34	  await page.getByLabel('Username').fill(username);
35	  await page.getByLabel('Password').fill('wrong password');
36	  await page.getByRole('button', { name: 'Log in' }).click();
37	  await expect(page.getByRole('alert')).toHaveText('Username or password is incorrect');
38	  await page.getByLabel('Username').fill(username.toUpperCase());
39	  await page.getByLabel('Password').fill(PASSWORD);
40	  await page.getByRole('button', { name: 'Log in' }).click();
41	  // US-33 #1: logging in always lands on the Dashboard.
42	  await expect(page.getByRole('heading', { level: 1, name: 'Dashboard' })).toBeVisible();
43	
44	  // US-01 #3: the same username can't be taken twice.
45	  await page.context().clearCookies();
46	  await page.goto('/signup');
47	  await page.getByLabel('Username').fill(username.toLowerCase());
48	  await page.getByLabel('Password').fill(PASSWORD);
49	  await page.getByRole('button', { name: 'Create account' }).click();
50	  await expect(page.getByText('That username is taken')).toBeVisible();

