await j('POST', '/auth/signup', { username: u, password: 'preview-only-pw' });
const g = await j('POST', '/groups', { name: 'Lake house weekend', currency: '$' });
for (const n of ['Ali', 'Sara', 'Omar']) await j('POST', `/groups/${g.groupId}/members`, { name: n });
const d = (await j('GET', `/groups/${g.groupId}`)).group;
const id = Object.fromEntries(d.members.map(m => [m.name, m.id]));
const base = { tax: { mode: 'percent', value: '8.25' }, otherCharges: { mode: 'amount', value: '12.00' }, tip: { mode: 'amount', value: '0' }, tipOn: 'items' };
await j('POST', `/groups/${g.groupId}/bills`, { bill: { ...base, name: 'Cabin booking', items: [{ name: 'Two nights', price: '360' }], splitMode: 'equal', participantIds: Object.values(id), payerId: id.Ali } });
await j('POST', `/groups/${g.groupId}/bills`, { bill: { ...base, name: 'Groceries run', items: [{ name: 'Market', price: '84.20', sharerIds: [id.Sara, id.Omar] }, { name: 'Firewood', price: '22', sharerIds: [d.meId] }], splitMode: 'itemized', participantIds: [d.meId, id.Sara, id.Omar], payerId: d.meId } });
const r = await j('POST', '/groups', { name: 'Flat 4B', currency: 'Rs' });
await j('POST', '/solo-bills', { currency: '€', bill: { ...base, name: 'Museum tickets', items: [{ name: '', price: '38.50' }] } });
location.href = '/';
