117	export function loadSession(ctx: AuthContext): RequestHandler {
118	  return async (req, res, next) => {
119	    const token = parseCookies(req.headers.cookie)[COOKIE_NAME];
120	    if (!token) return next();
121	    const hash = tokenHash(ctx.secret, token);
122	    const { rows } = await ctx.pool.query<{ id: number; username: string; theme: Theme; idle_ms: number }>(
123	      `SELECT a.id, a.username, a.theme,
124	              (EXTRACT(EPOCH FROM (now() - s.last_used_at)) * 1000)::bigint AS idle_ms
125	         FROM sessions s JOIN accounts a ON a.id = s.account_id
126	        WHERE s.token_hash = $1`,
127	      [hash],
128	    );
129	    const row = rows[0];
130	    if (!row || row.idle_ms > SESSION_MS) {
131	      if (row) await ctx.pool.query('DELETE FROM sessions WHERE token_hash = $1', [hash]);
