README.md:118:Logging in has no limit on attempts, by design. Checking a password takes deliberate effort, so on a public server a flood of login requests can slow the app down. If that becomes a problem, your reverse proxy can cap how many requests one address sends.
docs/user-stories.md:47:  - There is no limit on failed login or recovery-code attempts.
docs/user-stories.md:156:6. Given 20 wrong passwords in a row, when I then enter the correct one, then I'm logged in. There's no limit on attempts.
docs/user-stories.md:168:3. Given a wrong recovery code, or a username that doesn't exist, when I reset, then a clear message is shown and no password is changed.
docs/user-stories.md:170:5. Given many wrong recovery codes in a row, when I then enter the right one, then the reset works. There's no limit on attempts.
src/tests/api/accounts.test.ts:90:  it('#6 no limit on attempts', async () => {
src/tests/api/accounts.test.ts:152:  it('#5 no limit on attempts; codes can be typed in lower case', async () => {
import { createHmac, randomBytes, randomInt, scrypt, timingSafeEqual } from 'node:crypto';
import { Router, type RequestHandler, type Response } from 'express';
import { MESSAGES, checkPassword, checkUsername } from '../shared/rules.js';
import type { Account, Theme } from '../shared/api.js';
import { transaction, type Pool, type Queryable } from './db.js';
import { HttpError, badRequest } from './http.js';

const SESSION_DAYS = 30;
const SESSION_MS = SESSION_DAYS * 24 * 60 * 60 * 1000;
export const COOKIE_NAME = 'sid';

// ---------- Hashing (Node's built-in scrypt) ----------

const SCRYPT = { N: 16384, r: 8, p: 1, keylen: 64 };

function scryptAsync(secret: string, salt: Buffer): Promise<Buffer> {
  return new Promise((resolve, reject) =>
    scrypt(secret, salt, SCRYPT.keylen, { N: SCRYPT.N, r: SCRYPT.r, p: SCRYPT.p }, (err, key) =>
      err ? reject(err) : resolve(key),
    ),
  );
}

export async function hashSecret(secret: string): Promise<string> {
  const salt = randomBytes(16);
  const key = await scryptAsync(secret, salt);
  return `scrypt$${salt.toString('base64')}$${key.toString('base64')}`;
}

export async function verifySecret(secret: string, stored: string): Promise<boolean> {
  const [kind, saltB64, keyB64] = stored.split('$');
  if (kind !== 'scrypt' || !saltB64 || !keyB64) return false;
  const expected = Buffer.from(keyB64, 'base64');
  const actual = await scryptAsync(secret, Buffer.from(saltB64, 'base64'));
  return actual.length === expected.length && timingSafeEqual(actual, expected);
}

// A real hash to compare against when the username doesn't exist, so a wrong
// username takes as long as a wrong password.
let dummyHash: Promise<string> | null = null;

