// People and personal invites.
//
// Everyone added to a group by name is a "person". The same person can be in
// several groups. Each person without an account has their own invite code;
// using it links every group they're in to the new account at once.

import { randomInt } from 'node:crypto';
import { Router } from 'express';
import { MESSAGES, normalizeInviteCode } from '../shared/rules.js';
import type { InviteInfo, InviteResult, PersonOption } from '../shared/api.js';
import { currentAccount, requireAuth } from './auth.js';
import { transaction, type Client, type Pool, type Queryable } from './db.js';
import { HttpError } from './http.js';

const CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

function newInviteCode(): string {
  return Array.from({ length: 8 }, () => CODE_ALPHABET[randomInt(CODE_ALPHABET.length)]).join('');
}

/** Gives each listed person a code if they don't have one yet. Returns codes by person id. */
export async function ensureInviteCodes(db: Queryable, personIds: number[]): Promise<Map<number, string>> {
  const codes = new Map<number, string>();
  if (personIds.length === 0) return codes;
  const { rows } = await db.query<{ id: number; invite_code: string | null }>(
    'SELECT id, invite_code FROM persons WHERE id = ANY($1::bigint[]) AND account_id IS NULL',
    [personIds],
  );
  for (const row of rows) {
    let code = row.invite_code;
    while (!code) {
      const candidate = newInviteCode();
      const set = await db.query<{ invite_code: string }>(
        `UPDATE persons SET invite_code = COALESCE(invite_code, $2) WHERE id = $1
           AND NOT EXISTS (SELECT 1 FROM persons WHERE invite_code = $2) RETURNING invite_code`,
        [row.id, candidate],
      );
      code = set.rows[0]?.invite_code ?? null;
    }
    codes.set(row.id, code);
  }
  return codes;
}

/**
 * People I can add to `groupId`: everyone in any of my current groups (except me),
 * once each, who isn't already in that group.
 */
export async function myPeople(db: Queryable, accountId: number, groupId?: number): Promise<PersonOption[]> {
  const { rows } = await db.query<{ key: string; name: string; has_account: boolean; groups: string[] }>(
    `WITH mine AS (
       SELECT group_id FROM members WHERE account_id = $1 AND status = 'current'
     ),
     seen AS (
       SELECT CASE WHEN m.account_id IS NOT NULL THEN 'a:' || m.account_id ELSE 'p:' || m.person_id END AS key,
              COALESCE(a.username, p.name) AS name,
              m.account_id IS NOT NULL AS has_account,
              g.name AS group_name
         FROM members m
         JOIN mine ON mine.group_id = m.group_id
         JOIN groups g ON g.id = m.group_id
         LEFT JOIN accounts a ON a.id = m.account_id
         LEFT JOIN persons p ON p.id = m.person_id
        WHERE (m.account_id IS NULL OR m.account_id <> $1)
          AND (m.account_id IS NOT NULL OR m.person_id IS NOT NULL)
     )
     SELECT key, min(name) AS name, bool_or(has_account) AS has_account, array_agg(DISTINCT group_name) AS groups
       FROM seen
      WHERE $2::bigint IS NULL OR key NOT IN (
        SELECT CASE WHEN account_id IS NOT NULL THEN 'a:' || account_id ELSE 'p:' || person_id END
          FROM members WHERE group_id = $2 AND (account_id IS NOT NULL OR person_id IS NOT NULL))
      GROUP BY key
      ORDER BY lower(min(name)), key`,
    [accountId, groupId ?? null],
  );
  return rows.map((r) => ({ key: r.key, name: r.name, hasAccount: r.has_account, groups: r.groups.sort() }));
}

/**
 * Links every group a person is in to `accountId`. Groups where the account
 * is already a member are skipped; removed memberships are linked but stay
 * removed until someone restores them.
 */
export async function useInvite(client: Client, rawCode: unknown, accountId: number): Promise<InviteResult> {
  const code = normalizeInviteCode(rawCode);
  const person = (
    await client.query<{ id: number; account_id: number | null }>(
      'SELECT id, account_id FROM persons WHERE invite_code = $1 FOR UPDATE',
      [code],
    )
  ).rows[0];
  if (!code || !person) throw new HttpError(404, MESSAGES.inviteInvalid, { inviteCode: MESSAGES.inviteInvalid }, 'INVITE_INVALID');
  if (person.account_id !== null) throw new HttpError(409, MESSAGES.inviteUsed, { inviteCode: MESSAGES.inviteUsed }, 'INVITE_USED');

  const { rows } = await client.query<{ id: number; group_id: number; name: string; status: string; group_name: string }>(
    `SELECT m.id, m.group_id, m.name, m.status, g.name AS group_name
       FROM members m JOIN groups g ON g.id = m.group_id
      WHERE m.person_id = $1 ORDER BY lower(g.name), g.id FOR UPDATE OF m`,
    [person.id],
  );
  const result: InviteResult = { joined: [], removed: [], alreadyIn: [] };
  for (const m of rows) {
    const already = await client.query('SELECT 1 FROM members WHERE group_id = $1 AND account_id = $2', [m.group_id, accountId]);
    if (already.rows[0]) {
      result.alreadyIn.push(m.group_name);
      continue;
    }
    await client.query('UPDATE members SET account_id = $2 WHERE id = $1', [m.id, accountId]);
    await client.query('INSERT INTO activity (group_id, actor_name, message) VALUES ($1, $2, $3)', [
      m.group_id,
      m.name,
      `${m.name} joined with their invite`,
    ]);
    (m.status === 'current' ? result.joined : result.removed).push(m.group_name);
  }
  await client.query('UPDATE persons SET account_id = $2 WHERE id = $1', [person.id, accountId]);
  return result;
}

/** Public: what an invite link is for. Logged-out people need this before signing up. */
export async function inviteInfo(db: Queryable, rawCode: unknown): Promise<InviteInfo> {
  const code = normalizeInviteCode(rawCode);
  const person = (
    await db.query<{ id: number; name: string; account_id: number | null }>(
      'SELECT id, name, account_id FROM persons WHERE invite_code = $1',
      [code],
    )
  ).rows[0];
  if (!code || !person) throw new HttpError(404, MESSAGES.inviteInvalid, undefined, 'INVITE_INVALID');
  const { rows } = await db.query<{ name: string; group_name: string }>(
    `SELECT m.name, g.name AS group_name FROM members m JOIN groups g ON g.id = m.group_id
      WHERE m.person_id = $1 AND m.status = 'current' ORDER BY lower(g.name), g.id`,
    [person.id],
  );
  return { name: rows[0]?.name ?? person.name, groups: rows.map((r) => r.group_name), used: person.account_id !== null };
}

export function invitesRouter(pool: Pool): Router {
  const router = Router();

  router.get('/:code', async (req, res) => {
    res.json({ invite: await inviteInfo(pool, req.params.code) });
  });

  router.post('/:code/accept', requireAuth, async (req, res) => {
    const account = currentAccount(res);
    res.json({ result: await transaction(pool, (client) => useInvite(client, req.params.code, account.id)) });
  });

  return router;
}

export function peopleRouter(pool: Pool): Router {
  const router = Router();
  router.use(requireAuth);
  router.get('/', async (req, res) => {
    const groupId = /^\d{1,15}$/.test(String(req.query.groupId ?? '')) ? Number(req.query.groupId) : undefined;
    res.json({ people: await myPeople(pool, currentAccount(res).id, groupId) });
  });
  return router;
}

