1	// People and personal invites.
2	//
3	// Everyone added to a group by name is a "person". The same person can be in
4	// several groups. Each person without an account has their own invite code;
5	// using it links every group they're in to the new account at once.
6	
7	import { randomInt } from 'node:crypto';
8	import { Router } from 'express';
9	import { MESSAGES, normalizeInviteCode } from '../shared/rules.js';
10	import type { InviteInfo, InviteResult, PersonOption } from '../shared/api.js';
11	import { currentAccount, requireAuth } from './auth.js';
12	import { transaction, type Client, type Pool, type Queryable } from './db.js';
13	import { HttpError } from './http.js';
14	
15	const CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
16	
17	function newInviteCode(): string {
18	  return Array.from({ length: 8 }, () => CODE_ALPHABET[randomInt(CODE_ALPHABET.length)]).join('');
19	}
20	
21	/** Gives each listed person a code if they don't have one yet. Returns codes by person id. */
22	export async function ensureInviteCodes(db: Queryable, personIds: number[]): Promise<Map<number, string>> {
23	  const codes = new Map<number, string>();
24	  if (personIds.length === 0) return codes;
25	  const { rows } = await db.query<{ id: number; invite_code: string | null }>(
26	    'SELECT id, invite_code FROM persons WHERE id = ANY($1::bigint[]) AND account_id IS NULL',
27	    [personIds],
28	  );
29	  for (const row of rows) {
30	    let code = row.invite_code;
31	    while (!code) {
32	      try {
33	        const set = await db.query<{ invite_code: string }>(
34	          'UPDATE persons SET invite_code = COALESCE(invite_code, $2) WHERE id = $1 RETURNING invite_code',
35	          [row.id, newInviteCode()],
36	        );
37	        code = set.rows[0]?.invite_code ?? null;
38	      } catch (error) {
39	        // Another person already has that code (very rare): try a new one.
40	        if ((error as { code?: string }).code !== '23505') throw error;
41	      }
42	    }
43	    codes.set(row.id, code);
44	  }
45	  return codes;
46	}
47	
48	/**
49	 * People I can add to `groupId`: everyone in any of my current groups (except me),
50	 * once each, who isn't already in that group.
51	 */
52	export async function myPeople(db: Queryable, accountId: number, groupId?: number): Promise<PersonOption[]> {
53	  const { rows } = await db.query<{ key: string; name: string; has_account: boolean; groups: string[] }>(
54	    `WITH mine AS (
55	       SELECT group_id FROM members WHERE account_id = $1 AND status = 'current'
56	     ),
57	     seen AS (
58	       SELECT CASE WHEN m.account_id IS NOT NULL THEN 'a:' || m.account_id ELSE 'p:' || m.person_id END AS key,
59	              COALESCE(a.username, p.name) AS name,
60	              m.account_id IS NOT NULL AS has_account,
61	              g.name AS group_name
62	         FROM members m
63	         JOIN mine ON mine.group_id = m.group_id
64	         JOIN groups g ON g.id = m.group_id
65	         LEFT JOIN accounts a ON a.id = m.account_id
66	         LEFT JOIN persons p ON p.id = m.person_id
67	        WHERE (m.account_id IS NULL OR m.account_id <> $1)
68	          AND (m.account_id IS NOT NULL OR m.person_id IS NOT NULL)
69	     )
70	     SELECT key, min(name) AS name, bool_or(has_account) AS has_account, array_agg(DISTINCT group_name) AS groups
71	       FROM seen
72	      WHERE $2::bigint IS NULL OR key NOT IN (
73	        SELECT CASE WHEN account_id IS NOT NULL THEN 'a:' || account_id ELSE 'p:' || person_id END
74	          FROM members WHERE group_id = $2 AND (account_id IS NOT NULL OR person_id IS NOT NULL))
75	      GROUP BY key
76	      ORDER BY lower(min(name)), key`,
77	    [accountId, groupId ?? null],
78	  );
79	  return rows.map((r) => ({ key: r.key, name: r.name, hasAccount: r.has_account, groups: r.groups.sort() }));
80	}
81	
82	/**
83	 * Links every group a person is in to `accountId`. Groups where the account
84	 * is already a member are skipped; removed memberships are linked but stay
85	 * removed until someone restores them.
86	 */
87	export async function useInvite(client: Client, rawCode: unknown, accountId: number): Promise<InviteResult> {
88	  const code = normalizeInviteCode(rawCode);
89	  const person = (
90	    await client.query<{ id: number; account_id: number | null }>(
91	      'SELECT id, account_id FROM persons WHERE invite_code = $1 FOR UPDATE',
92	      [code],
93	    )
94	  ).rows[0];
95	  if (!code || !person) throw new HttpError(404, MESSAGES.inviteInvalid, { inviteCode: MESSAGES.inviteInvalid }, 'INVITE_INVALID');
96	  if (person.account_id !== null) throw new HttpError(409, MESSAGES.inviteUsed, { inviteCode: MESSAGES.inviteUsed }, 'INVITE_USED');
97	
98	  const { rows } = await client.query<{ id: number; group_id: number; name: string; status: string; group_name: string }>(
99	    `SELECT m.id, m.group_id, m.name, m.status, g.name AS group_name
100	       FROM members m JOIN groups g ON g.id = m.group_id
101	      WHERE m.person_id = $1 ORDER BY lower(g.name), g.id FOR UPDATE OF m`,
102	    [person.id],
103	  );
104	  // A person whose groups have all been deleted has nothing left to join.
105	  if (rows.length === 0) throw new HttpError(404, MESSAGES.inviteInvalid, { inviteCode: MESSAGES.inviteInvalid }, 'INVITE_INVALID');
106	  const result: InviteResult = { joined: [], removed: [], alreadyIn: [] };
107	  const mine = await client.query<{ group_id: number }>('SELECT group_id FROM members WHERE account_id = $1', [accountId]);
108	  const myGroups = new Set(mine.rows.map((r) => r.group_id));
109	  // Someone already in all of these groups is almost certainly a friend testing the
110	  // link, not the invited person: refuse, so the code stays usable.
111	  if (rows.length > 0 && rows.every((m) => myGroups.has(m.group_id))) {
112	    throw new HttpError(409, MESSAGES.inviteForSomeoneElse, undefined, 'INVITE_NOT_FOR_YOU');
113	  }
114	  for (const m of rows) {
115	    const already = await client.query('SELECT 1 FROM members WHERE group_id = $1 AND account_id = $2', [m.group_id, accountId]);
116	    if (already.rows[0]) {
117	      result.alreadyIn.push(m.group_name);
118	      continue;
119	    }
120	    await client.query('UPDATE members SET account_id = $2 WHERE id = $1', [m.id, accountId]);
121	    await client.query('INSERT INTO activity (group_id, actor_name, message) VALUES ($1, $2, $3)', [
122	      m.group_id,
123	      m.name,
124	      `${m.name} joined with their invite`,
125	    ]);
126	    (m.status === 'current' ? result.joined : result.removed).push(m.group_name);
127	  }
128	  await client.query('UPDATE persons SET account_id = $2 WHERE id = $1', [person.id, accountId]);
129	  return result;
130	}
131	
132	/** Public: what an invite link is for. Logged-out people need this before signing up. */
133	export async function inviteInfo(db: Queryable, rawCode: unknown, viewerAccountId?: number): Promise<InviteInfo> {
134	  const code = normalizeInviteCode(rawCode);
135	  const person = (
136	    await db.query<{ id: number; name: string; account_id: number | null }>(
137	      'SELECT id, name, account_id FROM persons WHERE invite_code = $1',
138	      [code],
139	    )
140	  ).rows[0];
141	  const anyMembership = person ? await db.query('SELECT 1 FROM members WHERE person_id = $1 LIMIT 1', [person.id]) : null;
142	  if (!code || !person || !anyMembership?.rows[0]) throw new HttpError(404, MESSAGES.inviteInvalid, undefined, 'INVITE_INVALID');
143	  const { rows } = await db.query<{ name: string; group_name: string; viewer_in: boolean }>(
144	    `SELECT m.name, g.name AS group_name,
145	            EXISTS (SELECT 1 FROM members v WHERE v.group_id = m.group_id AND v.account_id = $2) AS viewer_in
146	       FROM members m JOIN groups g ON g.id = m.group_id
147	      WHERE m.person_id = $1 AND m.status = 'current' ORDER BY lower(g.name), g.id`,
148	    [person.id, viewerAccountId ?? null],
149	  );
150	  return {
151	    name: rows[0]?.name ?? person.name,
152	    groups: rows.map((r) => r.group_name),
153	    used: person.account_id !== null,
