223	/** Checks a bill against the group's current members and works out its shares. */
224	function checkBillForGroup(body: unknown, members: MemberRow[]): { bill: GroupBill; result: ReturnType<typeof computeGroupBill> } {
225	  const input = ((body as { bill?: GroupBillInput })?.bill ?? {}) as GroupBillInput;
226	  const currentIds = members.filter((m) => m.status === 'current').map((m) => String(m.id));
227	  const ids = Array.isArray(input.participantIds) ? input.participantIds.map(String) : [];
228	  if (ids.some((id) => !currentIds.includes(id))) {
229	    throw fieldError({ participants: 'Only current members of this group can be on a bill' });
230	  }
231	  // People are kept in the group's member order, whatever order they were ticked in,
232	  // so who pays a leftover cent never depends on click history.
233	  const ordered = currentIds.filter((id) => ids.includes(id));
234	  const checked = checkGroupBill({ ...input, participantIds: ordered });
235	  if (!checked.ok) throw fieldError(checked.errors);
236	  return { bill: checked.value, result: computeGroupBill(checked.value) };
