399	        `INSERT INTO members (group_id, name, name_key, account_id, person_id) VALUES ($1, $2, $3, $4, $5)
400	         ON CONFLICT (group_id, name_key) DO NOTHING RETURNING id`,
401	        [m.group.id, name.value, nameKey(name.value), accountId, personId],
402	      );
403	      if (!rows[0]) throw new HttpError(409, MESSAGES.nameUsed, { name: MESSAGES.nameUsed });
404	      await logActivity(client, m.group.id, m.me.name, `${m.me.name} added ${name.value}`);
