1	import { useRef, useState, type FormEvent, type KeyboardEvent } from 'react';
2	import { Link, useNavigate, useParams, useSearchParams } from 'react-router-dom';
3	import type { ActivityDto, GroupBillSummary, GroupDetail, MemberDto, PersonOption, SettleUpDto } from '../../shared/api.js';
4	import { centsToInput } from '../../shared/money.js';
5	import { MESSAGES, checkMemberName } from '../../shared/rules.js';
6	import { ApiError, api } from '../api.js';
7	import { useBusy, useLoad } from '../hooks.js';
8	import { ConfirmDialog } from '../components/ConfirmDialog.js';
9	import { useToast } from '../components/Toasts.js';
10	import { Alert, Balance, EmptyState, ErrorText, PageHeader, Skeleton, TextField, money, niceDate, niceDateTime, usePageTitle } from '../components/ui.js';
11	
12	const TABS = [
13	  { id: 'bills', label: 'Bills' },
14	  { id: 'settle-ups', label: 'Settle-ups' },
15	  { id: 'members', label: 'Members' },
16	  { id: 'activity', label: 'Activity' },
17	] as const;
18	type TabId = (typeof TABS)[number]['id'];
19	
20	export function GroupPage() {
21	  const { groupId } = useParams();
22	  const { data, error, loading, reload } = useLoad(
23	    () => api.get<{ group: GroupDetail }>(`/groups/${groupId}`).then((r) => r.group),
24	    [groupId],
25	  );
26	  usePageTitle(data?.name ?? 'Group');
27	  const [params, setParams] = useSearchParams();
28	  const tab = (TABS.find((t) => t.id === params.get('tab'))?.id ?? 'bills') as TabId;
29	  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);
30	
31	  if (loading) return <Skeleton lines={6} />;
32	  if (error || !data) {
33	    return (
34	      <>
35	        <PageHeader title="Group" back={{ to: '/groups', label: 'Groups' }} />
36	        <Alert>{error?.message ?? MESSAGES.groupGone}</Alert>
37	      </>
38	    );
39	  }
40	
41	  const group = data;
42	  const names = new Map(group.members.map((m) => [m.id, m.status === 'removed' ? `${m.name} (removed)` : m.name]));
43	  const current = group.members.filter((m) => m.status === 'current');
44	
45	  const selectTab = (id: TabId, focus = false) => {
46	    setParams(id === 'bills' ? {} : { tab: id }, { replace: true });
47	    if (focus) tabRefs.current[TABS.findIndex((t) => t.id === id)]?.focus();
48	  };
49	  const onTabKey = (e: KeyboardEvent<HTMLDivElement>) => {
50	    // Count from the tab that has focus, so quick key presses never skip one.
51	    const focused = tabRefs.current.findIndex((el) => el === document.activeElement);
52	    const i = focused >= 0 ? focused : TABS.findIndex((t) => t.id === tab);
53	    let next = -1;
54	    if (e.key === 'ArrowRight') next = (i + 1) % TABS.length;
55	    else if (e.key === 'ArrowLeft') next = (i - 1 + TABS.length) % TABS.length;
56	    else if (e.key === 'Home') next = 0;
57	    else if (e.key === 'End') next = TABS.length - 1;
58	    if (next >= 0) {
59	      e.preventDefault();
60	      selectTab(TABS[next].id, true);
61	    }
62	  };
63	
64	  return (
65	    <>
66	      <PageHeader title={group.name} back={{ to: '/groups', label: 'Groups' }}>
67	        <Link className="btn btn-secondary" to={`/groups/${group.id}/edit`}>
68	          Edit group
69	        </Link>
70	        <Link className="btn btn-primary" to={`/groups/${group.id}/bills/new`}>
71	          Add bill
72	        </Link>
73	      </PageHeader>
74	      <p className="muted group-meta">Currency: {group.currency}</p>
75	
76	      <div className="grid-2">
77	        <section className="card" aria-labelledby="balances-heading">
78	          <h2 id="balances-heading" className="section-title">
79	            Balances
80	          </h2>
81	          <ul className="balance-list">
82	            {current.map((m) => (
83	              <li key={m.id} className="balance-row" data-testid="balance-row">
84	                <span className="person">
85	                  <span className="avatar" aria-hidden="true">
86	                    {Array.from(m.name)[0]?.toUpperCase()}
87	                  </span>
88	                  {m.name}
89	                  {m.isMe && <span className="muted"> (you)</span>}
90	                </span>
91	                <Balance cents={m.balanceCents} currency={group.currency} />
92	              </li>
93	            ))}
94	          </ul>
95	        </section>
96	        <section className="card" aria-labelledby="suggest-heading">
97	          <h2 id="suggest-heading" className="section-title">
98	            Suggested payments
99	          </h2>
100	          {group.suggestions.length === 0 ? (
101	            <p className="muted">Everyone is settled up.</p>
102	          ) : (
103	            <ul className="suggest-list">
104	              {group.suggestions.map((s) => (
105	                <li key={`${s.fromId}-${s.toId}`} className="suggest-row" data-testid="suggestion">
106	                  <span>
107	                    {names.get(s.fromId)} pays {names.get(s.toId)} {money(s.amountCents, group.currency)}
108	                  </span>
109	                  <Link
110	                    className="btn btn-secondary btn-small"
111	                    to={`/groups/${group.id}/settle-ups/new?from=${s.fromId}&to=${s.toId}&amount=${centsToInput(s.amountCents)}`}
112	                  >
113	                    Record this payment
114	                  </Link>
115	                </li>
116	              ))}
117	            </ul>
118	          )}
119	        </section>
120	      </div>
121	
122	      <div className="tabs" role="tablist" aria-label="Group sections" onKeyDown={onTabKey}>
123	        {TABS.map((t, i) => (
124	          <button
125	            key={t.id}
126	            ref={(el) => {
127	              tabRefs.current[i] = el;
128	            }}
129	            type="button"
130	            role="tab"
131	            id={`tab-${t.id}`}
132	            aria-selected={tab === t.id}
133	            aria-controls={`panel-${t.id}`}
134	            tabIndex={tab === t.id ? 0 : -1}
135	            className={tab === t.id ? 'tab tab-on' : 'tab'}
136	            onClick={() => selectTab(t.id)}
137	          >
138	            {t.label}
139	          </button>
140	        ))}
141	      </div>
142	      <div role="tabpanel" id={`panel-${tab}`} aria-labelledby={`tab-${tab}`} className="card tab-panel" tabIndex={0}>
143	        {tab === 'bills' && <BillsTab group={group} names={names} />}
144	        {tab === 'settle-ups' && <SettleUpsTab group={group} names={names} />}
145	        {tab === 'members' && <MembersTab group={group} reload={reload} />}
146	        {tab === 'activity' && <ActivityTab groupId={group.id} />}
147	      </div>
148	    </>
149	  );
150	}
151	
152	function BillsTab({ group, names }: { group: GroupDetail; names: Map<string, string> }) {
153	  const { data, error, loading } = useLoad(() => api.get<{ bills: GroupBillSummary[] }>(`/groups/${group.id}/bills`), [group.id]);
154	  if (loading) return <Skeleton lines={3} />;
155	  if (error) return <Alert>{error.message}</Alert>;
156	  if (!data || data.bills.length === 0) {
157	    return <EmptyState text="No bills yet. Add the first bill you shared." action={{ to: `/groups/${group.id}/bills/new`, label: 'Add bill' }} />;
158	  }
159	  return (
160	    <ul className="link-list">
161	      {data.bills.map((b) => (
162	        <li key={b.id}>
163	          <Link to={`/groups/${group.id}/bills/${b.id}`} className="link-row">
164	            <span className="link-row-title">
165	              {b.name}
166	              <span className="muted small">
167	                {' '}
168	                · {niceDate(b.date)} · paid by {names.get(b.payerId)} · {b.splitMode === 'equal' ? 'split equally' : 'by items'}
169	              </span>
170	              {b.lockedBy && <span className="badge badge-muted">View only</span>}
171	            </span>
172	            <span>{money(b.totalCents, group.currency)}</span>
173	          </Link>
174	        </li>
175	      ))}
176	    </ul>
177	  );
178	}
179	
180	function SettleUpsTab({ group, names }: { group: GroupDetail; names: Map<string, string> }) {
181	  const { data, error, loading } = useLoad(() => api.get<{ settleUps: SettleUpDto[] }>(`/groups/${group.id}/settle-ups`), [group.id]);
182	  if (loading) return <Skeleton lines={3} />;
183	  if (error) return <Alert>{error.message}</Alert>;
184	  return (
185	    <div className="stack">
186	      <div>
187	        <Link className="btn btn-secondary" to={`/groups/${group.id}/settle-ups/new`}>
188	          Record a payment
189	        </Link>
190	      </div>
191	      {!data || data.settleUps.length === 0 ? (
192	        <EmptyState text="No settle-ups yet. When someone pays another member back, record it here so balances stay right." />
193	      ) : (
194	        <ul className="link-list">
195	          {data.settleUps.map((s) => (
196	            <li key={s.id}>
197	              <Link to={`/groups/${group.id}/settle-ups/${s.id}`} className="link-row">
198	                <span className="link-row-title">
199	                  {names.get(s.fromId)} paid {names.get(s.toId)}
200	                  <span className="muted small"> · {niceDate(s.date)}</span>
201	                  {s.lockedBy && <span className="badge badge-muted">View only</span>}
202	                </span>
203	                <span>{money(s.amountCents, group.currency)}</span>
204	              </Link>
205	            </li>
206	          ))}
207	        </ul>
208	      )}
209	    </div>
210	  );
211	}
212	
213	type PendingAction = { kind: 'remove'; member: MemberDto } | { kind: 'leave' } | null;
214	
215	function inviteLink(code: string): string {
216	  return `${window.location.origin}/invite/${code}`;
217	}
218	
219	/** Code, Copy link and Share for one person who hasn't joined yet. */
220	function InviteControls({ member }: { member: MemberDto }) {
221	  const [copied, setCopied] = useState(false);
222	  if (!member.inviteCode) return null;
223	  const link = inviteLink(member.inviteCode);
224	  const canShare = typeof navigator.share === 'function';
225	  return (
226	    <div className="invite-row">
227	      <span className="muted small">
228	        Invite code <code className="invite-code-inline" data-testid={`invite-code-${member.name}`}>{member.inviteCode}</code>
229	      </span>
230	      <button
231	        type="button"
232	        className="btn btn-secondary btn-small"
233	        onClick={async () => {
234	          try {
235	            await navigator.clipboard.writeText(link);
236	            setCopied(true);
237	            window.setTimeout(() => setCopied(false), 3000);
238	          } catch {
239	            setCopied(false);
240	          }
241	        }}
242	      >
243	        {copied ? 'Copied' : 'Copy link'}
244	        <span className="visually-hidden"> for {member.name}</span>
245	      </button>
246	      {canShare && (
247	        <button
248	          type="button"
249	          className="btn btn-secondary btn-small"
250	          onClick={() => {
251	            navigator.share({ title: 'Bill Splitter', text: `${member.name}, join our groups on Bill Splitter`, url: link }).catch(() => {});
252	          }}
253	        >
254	          Share<span className="visually-hidden"> invite for {member.name}</span>
255	        </button>
256	      )}
257	    </div>
258	  );
259	}
260	
261	function MembersTab({ group, reload }: { group: GroupDetail; reload: () => Promise<void> }) {
262	  const toast = useToast();
263	  const navigate = useNavigate();
264	  const [newName, setNewName] = useState('');
265	  const [nameError, setNameError] = useState('');
266	  const [personKey, setPersonKey] = useState('');
267	  const [personError, setPersonError] = useState('');
268	  const [justAdded, setJustAdded] = useState<string | null>(null);
269	  const [renaming, setRenaming] = useState<string | null>(null);
270	  const [renameValue, setRenameValue] = useState('');
271	  const [renameError, setRenameError] = useState('');
272	  const [error, setError] = useState('');
273	  const [pending, setPending] = useState<PendingAction>(null);
274	  const { busy, run } = useBusy();
275	  const people = useLoad(() => api.get<{ people: PersonOption[] }>(`/people?groupId=${group.id}`).then((r) => r.people), [group.id, group.members.length]);
276	  const current = group.members.filter((m) => m.status === 'current');
277	  const removed = group.members.filter((m) => m.status === 'removed');
278	  const added = justAdded ? group.members.find((m) => m.id === justAdded) : undefined;
279	
280	  const afterAdd = async (memberId: string) => {
281	    toast('Member added');
282	    setJustAdded(memberId);
283	    await reload();
284	  };
285	
286	  const addMember = (e: FormEvent) => {
287	    e.preventDefault();
288	    const check = checkMemberName(newName);
289	    if (!check.ok) {
290	      setNameError(check.message);
291	      return;
292	    }
293	    void run(async () => {
294	      try {
295	        const r = await api.post<{ memberId: string }>(`/groups/${group.id}/members`, { name: newName });
296	        setNewName('');
297	        setNameError('');
298	        await afterAdd(r.memberId);
299	      } catch (err) {
300	        const e2 = err as ApiError;
301	        setNameError(e2.fields.name ?? e2.message);
302	      }
303	    });
304	  };
305	
306	  const addPerson = (e: FormEvent) => {
307	    e.preventDefault();
308	    if (!personKey) {
309	      setPersonError('Choose someone to add');
310	      return;
311	    }
312	    void run(async () => {
313	      try {
314	        const r = await api.post<{ memberId: string }>(`/groups/${group.id}/members`, { personKey });
315	        setPersonKey('');
316	        setPersonError('');
317	        await afterAdd(r.memberId);
318	      } catch (err) {
319	        const e2 = err as ApiError;
320	        setPersonError(e2.fields.name ?? e2.fields.person ?? e2.message);
321	      }
322	    });
323	  };
324	
325	  const saveRename = (member: MemberDto) =>
326	    run(async () => {
327	      const check = checkMemberName(renameValue);
328	      if (!check.ok) {
329	        setRenameError(check.message);
330	        return;
331	      }
332	      try {
333	        await api.put(`/groups/${group.id}/members/${member.id}`, { name: renameValue });
334	        setRenaming(null);
335	        setRenameError('');
336	        toast('Name changed');
337	        await reload();
338	      } catch (err) {
339	        const e2 = err as ApiError;
340	        setRenameError(e2.fields.name ?? e2.message);
341	      }
342	    });
343	
344	  const confirm = () =>
345	    run(async () => {
346	      if (!pending) return;
347	      setError('');
348	      try {
349	        if (pending.kind === 'remove') {
350	          await api.post(`/groups/${group.id}/members/${pending.member.id}/remove`);
351	          setPending(null);
352	          toast('Member removed');
353	          await reload();
354	        } else {
355	          const r = await api.post<{ outcome: 'left' | 'deleted' }>(`/groups/${group.id}/leave`, { confirmDelete: group.iAmLastAccount });
356	          setPending(null);
357	          toast(r.outcome === 'deleted' ? 'Group deleted' : 'You left the group');
358	          navigate('/groups', { replace: true });
359	        }
360	      } catch (err) {
361	        setPending(null);
362	        setError((err as ApiError).message);
363	      }
364	    });
365	
366	  const restore = (m: MemberDto) =>
367	    run(async () => {
