.subsection-title {
  font-size: 1rem;
  margin: 22px 0 10px;
}

.callout {
  padding: 16px 20px;
  border-radius: 14px;
  background: var(--accent-soft);
  font-weight: 600;
}

/* ---------- Dashboard money summary ---------- */

.grid-2:has(.summary-card) {
  gap: 0;
...
}

/* Codes */

.recovery-code,
.invite-code {
  padding: 12px 16px;
  border: 2px dashed var(--control);
  border-radius: 12px;
  background: var(--surface-2);
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  overflow-wrap: anywhere;
}

/* Long names with no spaces (usernames can be 30 characters) wrap instead of
   pushing the page sideways. */
.balance-row > span,
.suggest-row > span,
.member-row > span,
.activity-row > span,
.person,
.share-name,
.check span,
.picker-button {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* Password box with an eye button inside its right edge. */
.password-row {
  position: relative;
}

.password-row .input {
  padding-right: 52px;
}

.eye-button {
  position: absolute;
  top: 50%;
  right: 4px;
  transform: translateY(-50%);
  display: inline-grid;
  place-items: center;
  width: 40px;
  height: 36px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}

.eye-button:hover,
.eye-button[aria-pressed='true'] {
  color: var(--accent);
  background: var(--accent-soft);
}

.eye-button svg {
  width: 22px;
  height: 22px;
}

/* Invite page: one centred card. */
.public-single {
  grid-template-columns: minmax(0, 480px);
  justify-content: center;
}

.public-single .brand {
  margin-bottom: 20px;
}

.invite-groups {
  margin: 6px 0 0;
  padding-left: 20px;
  font-weight: 650;
}

.segmented-wide {
  display: flex;
}

.segmented-wide .seg {
  flex: 1;
}

/* Save sits under the receipt. */
.save-bar {
  display: grid;
  gap: 12px;
  justify-items: start;
  max-width: 560px;
  margin-top: 20px;
}

.totals .rate {
  font-size: 0.875rem;
}

/* Members: name and buttons on one line, invite controls underneath. */
.member-row-stack {
  display: grid;
  gap: 8px;
}

.member-main {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 6px 12px;
  min-width: 0;
}

.member-actions,
.invite-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.invite-code-inline {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--ink);
}

.alert .invite-row {
  margin-top: 10px;
}

.rename-form {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  gap: 8px;
}

.rename-form .field {
  flex: 1 1 200px;
}

.rename-form .field-label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Dashboard: who I owe and who owes me. */
.debt-list {
  list-style: none;
  margin: 14px 0 0;
  padding: 12px 0 0;
  border-top: 1px dashed var(--line);
  display: grid;
  gap: 8px;
}

.debt-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  min-width: 0;
}

