interface Props {
  open: boolean;
  title: string;
  children?: ReactNode;
  confirmLabel: string;
  cancelLabel?: string;
  /** Red confirm button for actions that delete or remove things. */
  danger?: boolean;
  busy?: boolean;
  onConfirm: () => void;
  onCancel: () => void;
}

/**
 * A modal pop-up. The browser keeps keyboard focus inside it, and Esc works
 * like Cancel. The safe button is focused first.
 */
