}
async function code(page: Page, groupId: string, name: string) {
  return (await members(page, groupId)).find((m) => m.name === name)?.inviteCode as string;
}
async function group(page: Page, name: string, people: string[]) {
  const { groupId } = await api<{ groupId: string }>(page, 'post', '/groups', { name, currency: 'Rs' });
  for (const p of people) await api(page, 'post', `/groups/${groupId}/members`, { name: p });
  return groupId;
}
async function addFromPeople(page: Page, groupId: string, name: string) {
  const { people } = await api<{ people: { key: string; name: string }[] }>(page, 'get', `/people?groupId=${groupId}`);
  return api(page, 'post', `/groups/${groupId}/members`, { personKey: people.find((p) => p.name === name)?.key });
}

for (const width of [1280, 375]) {
  test(`shots at ${width}`, async ({ browser }) => {
    test.setTimeout(120_000);
    const tag = width === 375 ? 'phone' : 'desk';
    const owner = await account(browser, 'own');
    const sara = await account(browser, 'sara');
