    for (const p of [owner.page, sara.page, pat.page]) await p.setViewportSize({ width, height: 900 });

    const dinner = await group(owner.page, 'Dinner club', ['Sara', 'Pat', 'Omar']);
    const trip = await group(owner.page, 'Beach trip', []);
    await addFromPeople(owner.page, trip, 'Omar');
    await api(sara.page, 'post', `/invites/${await code(owner.page, dinner, 'Sara')}/accept`);

    // 1. Owner adds Ghania by name: the "Invite Ghania" box.
    await owner.page.goto(`/groups/${dinner}?tab=members`);
    await owner.page.getByLabel('Add a friend by name').fill('Ghania');
    await owner.page.getByRole('button', { name: 'Add member' }).click();
    await expect(owner.page.getByRole('region', { name: 'Invite Ghania' })).toBeVisible();
    await owner.page.screenshot({ path: `${OUT}/${tag}-1-invite-box.png`, fullPage: true });

