    await expect(sara.page.getByText("Only someone who's in all of Omar's groups can send their invite.")).toBeVisible();
    await sara.page.getByText("Only someone who's in all of Omar's groups").scrollIntoViewIfNeeded();
    await sara.page.screenshot({ path: `${OUT}/${tag}-2-hidden-code.png`, fullPage: true });

    // 3. Name clash when adding from other groups.
    const club = await group(owner.page, 'Book club', ['Omar']);
    await owner.page.goto(`/groups/${club}?tab=members`);
    await owner.page.getByLabel('Or add someone from your other groups').selectOption({ label: 'Omar (Beach trip, Dinner club)' });
    await owner.page.getByRole('button', { name: 'Add to group' }).click();
    await expect(owner.page.getByLabel('Name in this group')).toBeVisible();
    await owner.page.screenshot({ path: `${OUT}/${tag}-3-name-clash.png`, fullPage: true });

    // 4. Copy link without a clipboard.
    await owner.page.goto(`/groups/${dinner}?tab=members`);
    await owner.page.evaluate(() => {
      Object.defineProperty(navigator, 'clipboard', { value: { writeText: () => Promise.reject(new Error('no')) }, configurable: true });
    });
    await owner.page.getByRole('button', { name: 'Copy link for Ghania' }).click();
    await expect(owner.page.getByLabel('Invite link for Ghania')).toBeVisible();
    await owner.page.getByLabel('Invite link for Ghania').scrollIntoViewIfNeeded();
    await owner.page.screenshot({ path: `${OUT}/${tag}-4-copy-fallback.png`, fullPage: true });

    // 5. Pat's account is in Dinner as Pat, then opens Omar's link: warning, then the confirm dialog.
    await api(pat.page, 'post', `/invites/${await code(owner.page, dinner, 'Pat')}/accept`);
    const omarCode = await code(owner.page, dinner, 'Omar');
    await pat.page.goto(`/invite/${omarCode}`);
    await expect(pat.page.getByText("If you're not Omar, don't join")).toBeVisible();
    await pat.page.screenshot({ path: `${OUT}/${tag}-5-invite-warning.png`, fullPage: true });
    await pat.page.getByRole('button', { name: 'Join these groups' }).click();
    await expect(pat.page.getByRole('dialog', { name: 'Join as Omar?' })).toBeVisible();
    await pat.page.screenshot({ path: `${OUT}/${tag}-6-invite-confirm.png` });
    await pat.page.getByRole('button', { name: 'Join as Omar' }).click();
    await expect(pat.page.getByRole('heading', { level: 1, name: 'Dashboard' })).toBeVisible();
    await pat.page.screenshot({ path: `${OUT}/${tag}-7-joined-toast.png` });

    // 6. Used invite.
    await sara.page.goto(`/invite/${omarCode}`);
    await expect(sara.page.getByRole('heading', { level: 1, name: 'Invite already used' })).toBeVisible();
    await sara.page.screenshot({ path: `${OUT}/${tag}-8-used.png` });

    // 7. "already here as Pat" in Dinner.
    await owner.page.goto(`/groups/${dinner}?tab=members`);
    await expect(owner.page.getByText('already here as Pat')).toBeVisible();
    await owner.page.screenshot({ path: `${OUT}/${tag}-9-already-here.png`, fullPage: true });

    // 8. Dashboard debts + password eye.
    const ids = Object.fromEntries((await members(owner.page, dinner)).map((m) => [m.name, m.id]));
    const me = (await api<{ group: { meId: string } }>(owner.page, 'get', `/groups/${dinner}`)).group.meId;
    await api(owner.page, 'post', `/groups/${dinner}/bills`, {
      bill: {
        name: 'Pizza', items: [{ name: '', price: '900' }], tax: { mode: 'amount', value: '0' }, otherCharges: { mode: 'amount', value: '' },
        tip: { mode: 'amount', value: '0' }, tipOn: 'items', splitMode: 'equal', participantIds: [me, ids.Sara, ids.Ghania], payerId: ids.Sara,
      },
    });
    await owner.page.goto('/');
    await expect(owner.page.getByRole('list', { name: 'Who you owe' })).toBeVisible();
    await owner.page.screenshot({ path: `${OUT}/${tag}-10-dashboard.png`, fullPage: true });

    const guest = await (await browser.newContext()).newPage();
    await guest.setViewportSize({ width, height: 900 });
    await guest.goto('/login');
    await guest.getByLabel('Password', { exact: true }).fill('secret pass');
    await guest.getByRole('button', { name: 'Show password' }).click();
    await guest.screenshot({ path: `${OUT}/${tag}-11-eye.png` });
  });
}

