1	// Form state for the bill screens, and the Calculate step (the same checks and
2	// maths the server uses when saving).
3	
4	import {
5	  checkBill,
6	  checkGroupBill,
7	  computeGroupBill,
8	  computeTotals,
9	  type BillInput,
10	  type ChargeInput,
11	  type FieldErrors,
12	  type GroupBillInput,
13	  type Share,
14	  type SplitMode,
15	  type TipOn,
16	  type Totals,
17	} from '../shared/bill.js';
18	import { CURRENCIES, MAX_ITEMS, checkCurrency } from '../shared/rules.js';
19	import { formatPercent, parseHundredths } from '../shared/money.js';
20	
21	export interface ItemRow {
22	  key: number;
23	  name: string;
24	  price: string;
25	  sharerIds: string[];
26	}
27	
28	export interface BillFormState {
29	  name: string;
30	  items: ItemRow[];
31	  tax: ChargeInput;
32	  otherCharges: ChargeInput;
33	  tip: ChargeInput;
34	  tipOn: TipOn;
35	  /** Solo bills: one of the listed symbols, or "other". */
36	  currencyChoice: string;
37	  customCurrency: string;
38	  /** Group bills. */
39	  splitMode: SplitMode;
40	  participantIds: string[];
41	  payerId: string | null;
42	}
43	
44	let nextKey = 1;
45	export const newItem = (over: Partial<ItemRow> = {}): ItemRow => ({ key: nextKey++, name: '', price: '', sharerIds: [], ...over });
46	
47	export function emptyBill(over: Partial<BillFormState> = {}): BillFormState {
48	  return {
49	    name: '',
50	    items: [newItem()],
51	    // Blank means 0, so typing starts from an empty box ("5", not "05").
52	    tax: { mode: 'percent', value: '' },
53	    otherCharges: { mode: 'amount', value: '' },
54	    tip: { mode: 'percent', value: '' },
55	    tipOn: 'items',
56	    currencyChoice: '$',
57	    customCurrency: '',
58	    splitMode: 'equal',
59	    participantIds: [],
60	    payerId: null,
61	    ...over,
62	  };
63	}
64	
65	/** Rebuilds the form from a saved bill. */
66	export function fromInput(input: BillInput | GroupBillInput, currency?: string): BillFormState {
67	  const group = input as Partial<GroupBillInput>;
68	  const listed = currency !== undefined && (CURRENCIES as readonly string[]).includes(currency);
69	  return emptyBill({
70	    name: input.name,
71	    items: input.items.map((it) => newItem({ name: it.name, price: it.price, sharerIds: it.sharerIds ?? [] })),
72	    tax: input.tax,
73	    otherCharges: input.otherCharges,
74	    tip: input.tip,
75	    tipOn: input.tipOn,
76	    currencyChoice: currency === undefined ? '$' : listed ? currency : 'other',
77	    customCurrency: currency !== undefined && !listed ? currency : '',
78	    splitMode: group.splitMode ?? 'equal',
79	    participantIds: group.participantIds ?? [],
80	    payerId: group.payerId ?? null,
81	  });
82	}
83	
84	export function toBillInput(state: BillFormState): BillInput {
85	  return {
86	    name: state.name,
87	    items: state.items.map((it) => ({ name: it.name, price: it.price })),
88	    tax: state.tax,
89	    otherCharges: state.otherCharges,
90	    tip: state.tip,
91	    tipOn: state.tipOn,
92	  };
93	}
94	
95	export function toGroupBillInput(state: BillFormState): GroupBillInput {
96	  return {
97	    ...toBillInput(state),
98	    items: state.items.map((it) => ({ name: it.name, price: it.price, sharerIds: it.sharerIds })),
99	    splitMode: state.splitMode,
100	    participantIds: state.participantIds,
101	    payerId: state.payerId,
102	  };
103	}
104	
105	export function chosenCurrency(state: BillFormState): string {
106	  return state.currencyChoice === 'other' ? state.customCurrency : state.currencyChoice;
107	}
108	
109	export interface CalcResult {
110	  totals: Totals;
111	  shares: Share[] | null;
112	}
113	
114	export type CalcOutcome = { ok: true; result: CalcResult } | { ok: false; errors: FieldErrors };
115	
116	/** Runs every check; returns the result only when everything is valid. */
117	export function calculate(state: BillFormState, kind: 'solo' | 'group', checkSoloCurrency: boolean): CalcOutcome {
118	  if (kind === 'group') {
119	    const checked = checkGroupBill(toGroupBillInput(state));
120	    if (!checked.ok) return { ok: false, errors: checked.errors };
121	    const r = computeGroupBill(checked.value);
122	    return { ok: true, result: { totals: r.totals, shares: r.shares } };
123	  }
124	  const checked = checkBill(toBillInput(state));
125	  const errors: FieldErrors = checked.ok ? {} : { ...checked.errors };
126	  if (checkSoloCurrency) {
127	    const currency = checkCurrency(chosenCurrency(state));
128	    if (!currency.ok) errors.currency = currency.message;
129	  }
130	  if (!checked.ok || Object.keys(errors).length > 0) return { ok: false, errors };
131	  return { ok: true, result: { totals: computeTotals(checked.value), shares: null } };
132	}
133	
134	export function canAddItem(state: BillFormState): boolean {
135	  return state.items.length < MAX_ITEMS;
136	}
137	
138	
139	/** Item keys are only for React; they don't count as unsaved changes. */
140	export function stripKeys(state: BillFormState) {
141	  return { ...state, items: state.items.map(({ name, price, sharerIds }) => ({ name, price, sharerIds })) };
142	}
143	
144	/** Smooth scrolling, unless the person has asked their device to reduce motion. */
145	function scrollBehavior(): ScrollBehavior {
146	  return window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';
147	}
148	
149	/** After Calculate: bring the results into view and move focus there, so they are read out. */
150	export function revealResults(results: HTMLElement | null): void {
151	  window.setTimeout(() => {
152	    results?.scrollIntoView({ behavior: scrollBehavior(), block: 'start' });
153	    results?.focus({ preventScroll: true });
154	  }, 0);
155	}
156	
157	/** Moves keyboard focus to the first field with a problem. */
158	export function focusFirstError(root: HTMLElement | null): void {
159	  const target = root?.querySelector<HTMLElement>('[aria-invalid="true"], [data-error-anchor]');
160	  target?.focus();
161	}
162	
163	export interface RateLabels {
164	  tax: string;
165	  other: string;
166	  tip: string;
167	}
168	
169	/** The rate behind each results line: "(5%)", "(15% of items + tax)". Blank for amounts. */
170	export function rateLabels(state: BillFormState): RateLabels {
171	  // A blank box counts as nothing, so it gets no rate.
172	  const pct = (c: ChargeInput) => {
173	    if (c.mode !== 'percent' || c.value.trim() === '') return null;
174	    const bp = parseHundredths(c.value);
175	    return bp === null ? null : `${formatPercent(bp)}%`;
176	  };
177	  const tax = pct(state.tax);
178	  const other = pct(state.otherCharges);
179	  const tip = pct(state.tip);
180	  return {
181	    tax: tax ? `(${tax})` : '',
182	    other: other ? `(${other})` : '',
183	    tip: tip ? `(${tip} of ${state.tipOn === 'items_tax' ? 'items + tax' : 'items'})` : '',
184	  };
185	}
186

1	import { useEffect, useId, useRef, useState, type KeyboardEvent } from 'react';
2	import { MESSAGES } from '../../shared/rules.js';
3	
4	interface Person {
5	  id: string;
6	  name: string;
7	}
8	
9	interface Props {
10	  label: string;
11	  people: Person[];
12	  selected: string[];
13	  onChange: (ids: string[]) => void;
14	  error?: string;
15	}
16	
17	/**
18	 * A dropdown with a tick box per person. Closed, it shows the ticked names.
19	 * Keyboard: Enter/Space opens, arrow keys move, Space ticks, Esc closes.
20	 */
21	export function PeoplePicker({ label, people, selected, onChange, error }: Props) {
22	  const [open, setOpen] = useState(false);
23	  const wrapRef = useRef<HTMLDivElement>(null);
24	  const buttonRef = useRef<HTMLButtonElement>(null);
25	  const panelId = useId();
26	  const errorId = useId();
27	  const names = people.filter((p) => selected.includes(p.id)).map((p) => p.name);
28	
29	  useEffect(() => {
30	    if (!open) return;
31	    const onDoc = (e: MouseEvent) => {
32	      if (!wrapRef.current?.contains(e.target as Node)) setOpen(false);
33	    };
34	    document.addEventListener('mousedown', onDoc);
35	    const first = wrapRef.current?.querySelector<HTMLInputElement>('input[type=checkbox]');
36	    first?.focus();
37	    return () => document.removeEventListener('mousedown', onDoc);
38	  }, [open]);
39	
40	  const toggle = (id: string) => {
41	    onChange(selected.includes(id) ? selected.filter((x) => x !== id) : [...selected, id]);
42	  };
43	
44	  const onPanelKey = (e: KeyboardEvent<HTMLDivElement>) => {
45	    const boxes = Array.from(wrapRef.current?.querySelectorAll<HTMLInputElement>('input[type=checkbox]') ?? []);
46	    const i = boxes.indexOf(document.activeElement as HTMLInputElement);
47	    if (e.key === 'Escape') {
48	      e.preventDefault();
49	      e.stopPropagation();
50	      setOpen(false);
51	      buttonRef.current?.focus();
52	    } else if (e.key === 'ArrowDown' && boxes.length) {
53	      e.preventDefault();
54	      boxes[(i + 1) % boxes.length].focus();
55	    } else if (e.key === 'ArrowUp' && boxes.length) {
56	      e.preventDefault();
57	      boxes[(i - 1 + boxes.length) % boxes.length].focus();
58	    }
59	  };
60	
61	  return (
62	    <div className="picker" ref={wrapRef}>
63	      <button
64	        ref={buttonRef}
65	        type="button"
66	        className={`picker-button${names.length ? '' : ' picker-empty'}`}
67	        aria-expanded={open}
68	        aria-controls={panelId}
69	        aria-invalid={error ? true : undefined}
70	        aria-describedby={error ? errorId : undefined}
71	        onClick={() => setOpen((o) => !o)}
72	      >
73	        <span className="visually-hidden">{label}: </span>
74	        {names.length ? names.join(', ') : MESSAGES.noSharers}
75	        <span aria-hidden="true" className="picker-caret">
76	          ▾
77	        </span>
78	      </button>
79	      {open && (
80	        <div id={panelId} className="picker-panel" onKeyDown={onPanelKey}>
81	          <fieldset>
82	            <legend className="visually-hidden">{label}</legend>
83	            {people.length === 0 && <p className="muted">Tick who took part first.</p>}
84	            {people.map((p) => (
85	              <label key={p.id} className="check">
86	                <input type="checkbox" checked={selected.includes(p.id)} onChange={() => toggle(p.id)} />
87	                <span>{p.name}</span>
88	              </label>
89	            ))}
90	          </fieldset>
91	          <button
92	            type="button"
93	            className="btn btn-secondary btn-small"
94	            onClick={() => {
95	              setOpen(false);
96	              buttonRef.current?.focus();
97	            }}
98	          >
99	            Done
100	          </button>
101	        </div>
102	      )}
103	      {error && (
104	        <p id={errorId} className="field-error">
105	          {error}
106	        </p>
107	      )}
108	    </div>
109	  );
110	}
