1	import { useMemo, useRef, useState } from 'react';
2	import { Link, useNavigate, useParams } from 'react-router-dom';
3	import type { FieldErrors } from '../../shared/bill.js';
4	import type { SoloBillDetail, SoloBillSummary } from '../../shared/api.js';
5	import { ApiError, api } from '../api.js';
6	import { calculate, chosenCurrency, emptyBill, focusFirstError, fromInput, rateLabels, revealResults, stripKeys, toBillInput, type BillFormState, type CalcResult } from '../billEditor.js';
7	import { clearFieldError, withoutKey } from '../fieldErrors.js';
8	import { useBusy, useFocusFirstError, useLoad } from '../hooks.js';
9	import { BillForm } from '../components/BillForm.js';
10	import { ConfirmDialog } from '../components/ConfirmDialog.js';
11	import { CurrencyPicker } from '../components/CurrencyPicker.js';
12	import { Results } from '../components/Results.js';
13	import { useToast } from '../components/Toasts.js';
14	import { useUnsavedGuard } from '../components/UnsavedGuard.js';
15	import { Alert, EmptyState, PageHeader, Skeleton, money, niceDate, usePageTitle } from '../components/ui.js';
16	
17	export function SoloListPage() {
18	  usePageTitle('Solo bills');
19	  const { data, error, loading } = useLoad(() => api.get<{ bills: SoloBillSummary[] }>('/solo-bills'), []);
20	  return (
21	    <>
22	      <PageHeader title="Solo bills">
23	        <Link className="btn btn-primary" to="/solo/new">
24	          New solo bill
25	        </Link>
26	      </PageHeader>
27	      <Alert>{error?.message}</Alert>
28	      {loading && <Skeleton lines={4} />}
29	      {data &&
30	        (data.bills.length === 0 ? (
31	          <div className="card">
32	            <EmptyState text="No solo bills yet. Total your first bill to keep a record of it." action={{ to: '/solo/new', label: 'New solo bill' }} />
33	          </div>
34	        ) : (
35	          <ul className="link-list card">
36	            {data.bills.map((b) => (
37	              <li key={b.id}>
38	                <Link to={`/solo/${b.id}`} className="link-row">
39	                  <span className="link-row-title">
40	                    {b.name}
41	                    <span className="muted small"> · {niceDate(b.date)} · {b.currency}</span>
42	                  </span>
43	                  <span>{money(b.totalCents, b.currency)}</span>
44	                </Link>
45	              </li>
46	            ))}
47	          </ul>
48	        ))}
49	    </>
50	  );
51	}
52	
53	/** New solo bill (no id) or a saved one (opened for editing). */
54	export function SoloBillPage() {
55	  const { id } = useParams();
56	  const isNew = id === undefined;
57	  const { data, error, loading, reload } = useLoad(
58	    () => (isNew ? Promise.resolve(null) : api.get<{ bill: SoloBillDetail }>(`/solo-bills/${id}`).then((r) => r.bill)),
59	    [id],
60	  );
61	  usePageTitle(isNew ? 'New solo bill' : (data?.name ?? 'Solo bill'));
62	  const [version, setVersion] = useState(0);
63	
64	  if (loading) return <Skeleton lines={6} />;
65	  if (error) {
66	    return (
67	      <>
68	        <PageHeader title="Solo bill" back={{ to: '/solo', label: 'Solo bills' }} />
69	        <Alert>{error.message}</Alert>
70	      </>
71	    );
72	  }
73	  return (
74	    <SoloBillEditor
75	      key={`${id ?? 'new'}-${version}`}
76	      saved={data}
77	      onSavedEdit={() => reload().then(() => setVersion((v) => v + 1))}
78	    />
79	  );
80	}
81	
82	function SoloBillEditor({ saved, onSavedEdit }: { saved: SoloBillDetail | null; onSavedEdit: () => void }) {
83	  const navigate = useNavigate();
84	  const toast = useToast();
85	  const initial = useMemo(() => (saved ? fromInput(saved.input, saved.currency) : emptyBill()), [saved]);
86	  const [state, setState] = useState<BillFormState>(initial);
87	  const [snapshot, setSnapshot] = useState(() => JSON.stringify(stripKeys(initial)));
88	  const [errors, setErrors] = useState<FieldErrors>({});
89	  const [result, setResult] = useState<CalcResult | null>(saved ? { totals: saved.totals, shares: null } : null);
90	  const [pageError, setPageError] = useState('');
91	  // Problems with Delete show at the top, next to the button that caused them.
92	  const [headerError, setHeaderError] = useState('');
93	  const [confirmDelete, setConfirmDelete] = useState(false);
94	  const { busy, run } = useBusy();
95	  const formRef = useRef<HTMLFormElement>(null);
96	  const resultsRef = useRef<HTMLElement>(null);
97	  const focusErrors = useFocusFirstError(formRef);
98	  const dirty = JSON.stringify(stripKeys(state)) !== snapshot;
99	  const guard = useUnsavedGuard(dirty);
100	  const currency = saved ? saved.currency : chosenCurrency(state);
101	
102	  const change = (next: BillFormState) => {
103	    setState(next);
104	    setResult(null); // any change hides the old result
105	  };
106	
107	  const onCalculate = () => {
108	    const outcome = calculate(state, 'solo', !saved);
109	    if (!outcome.ok) {
110	      setErrors(outcome.errors);
111	      setResult(null);
112	      window.setTimeout(() => focusFirstError(formRef.current), 0);
113	      return;
114	    }
115	    setErrors({});
116	    setResult(outcome.result);
117	    revealResults(resultsRef.current);
118	  };
119	
120	  const onSave = () =>
121	    run(async () => {
122	      setPageError('');
123	      const outcome = calculate(state, 'solo', !saved);
124	      if (!outcome.ok) {
125	        setErrors(outcome.errors);
126	        window.setTimeout(() => focusFirstError(formRef.current), 0);
127	        return;
128	      }
129	      setErrors({});
130	      try {
131	        const body = { currency: chosenCurrency(state), bill: toBillInput(state) };
132	        const r = saved
133	          ? await api.put<{ bill: SoloBillSummary }>(`/solo-bills/${saved.id}`, body)
134	          : await api.post<{ bill: SoloBillSummary }>('/solo-bills', body);
135	        setSnapshot(JSON.stringify(stripKeys(state)));
136	        toast('Bill saved');
137	        if (saved) {
138	          onSavedEdit();
139	        } else {
140	          guard.allowLeave();
141	          navigate(`/solo/${r.bill.id}`, { replace: true });
142	        }
143	      } catch (err) {
144	        const e = err as ApiError;
145	        setErrors(e.fields);
146	        setPageError(e.message);
147	        if (Object.keys(e.fields).length) focusErrors();
148	      }
149	    });
150	
151	  const onDelete = () =>
152	    run(async () => {
153	      if (!saved) return;
154	      setHeaderError('');
155	      try {
156	        await api.del(`/solo-bills/${saved.id}`);
157	        guard.allowLeave();
158	        setConfirmDelete(false);
159	        toast('Bill deleted');
160	        navigate('/solo', { replace: true });
161	      } catch (err) {
162	        setConfirmDelete(false);
163	        setHeaderError((err as ApiError).message);
164	      }
165	    });
166	
167	  return (
168	    <>
169	      <PageHeader title={saved ? saved.name : 'New solo bill'} back={{ to: '/solo', label: 'Solo bills' }}>
170	        {saved && (
171	          <button type="button" className="btn btn-danger-outline" onClick={() => setConfirmDelete(true)}>
172	            Delete
173	          </button>
174	        )}
175	      </PageHeader>
176	      <Alert>{headerError}</Alert>
177	      <form
178	        ref={formRef}
179	        className="card stack"
180	        noValidate
181	        onSubmit={(e) => {
182	          e.preventDefault();
183	          onCalculate();
184	        }}
185	      >
186	        {saved ? (
187	          <div className="field">
188	            <span className="field-label">Currency</span>
189	            <p>
190	              <strong>{saved.currency}</strong> <span className="muted">— can't be changed after the bill is saved.</span>
191	            </p>
192	          </div>
193	        ) : (
194	          <CurrencyPicker
195	            choice={state.currencyChoice}
196	            custom={state.customCurrency}
197	            note="Only changes the symbol shown; nothing is converted. It can't be changed after you save."
