    --on-danger: #2a0b08;
    --success: #7fd8a4;
    --focus: #e6a6d8;
    --paper: #1f2723;
    --skeleton: #29322e;
    --lift: none;
    --lift-high: 0 12px 32px rgba(0, 0, 0, 0.45);
  }
}

