/* ---------- Page structure ---------- */

.page-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px 16px;
  margin-bottom: 28px;
}

.page-title {
  font-size: 2.25rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  overflow-wrap: anywhere;
}

@media (max-width: 767px) {
  .page-title {
    font-size: 1.75rem;
  }
}

.page-actions,
.row,
.form-actions,
.radio-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 12px;
  align-items: center;
}

.back-link {
  display: inline-block;
  margin-bottom: 8px;
  padding: 2px 0;
  color: var(--muted);
  font-weight: 600;
  text-decoration: none;
}

.back-link:hover {
  color: var(--accent);
}

.group-meta {
  margin: -18px 0 24px;
}

.stack {
  display: grid;
  gap: 18px;
}

.stack-lg {
  display: grid;
  gap: 28px;
}

.narrow {
  max-width: 580px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
  margin-bottom: 28px;
}

