file.content:
.stack-lg > .card + .card {
  margin-top: 0;
}

@media (max-width: 900px) {
  .grid-2 {
    grid-template-columns: minmax(0, 1fr);
  }
}

.card {
  min-width: 0;
  padding: 28px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: var(--lift);
}

@media (max-width: 767px) {
  .card {
    padding: 18px;
    border-radius: 14px;
  }
}

.card + .card,
.card + .receipt-wrap,
form.card + .receipt-wrap {
  margin-top: 24px;
}

.section-title {
  font-size: 1.1875rem;
  font-weight: 650;
  margin-bottom: 14px;
}

.subsection-title {
  font-size: 1rem;
  margin: 22px 0 10px;
}

.callout {
  padding: 16px 20px;
  border-radius: 14px;
  background: var(--accent-soft);
  font-weight: 600;
}

/* ---------- Dashboard money summary ---------- */

.grid-2:has(.summary-card) {
  gap: 0;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: var(--lift);
  overflow: hidden;
}

.summary-card {
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.summary-card + .summary-card {
  margin-top: 0;
  border-left: 1px solid var(--line);
}

@media (max-width: 900px) {
  .summary-card + .summary-card {
    border-left: 0;
    border-top: 1px solid var(--line);
  }
}

.summary-card .section-title {
  font-family: var(--font-body);
  font-size: 1rem;
  color: var(--muted);
  font-weight: 600;
  margin-bottom: 8px;
}

.summary-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 2px;
}

.summary-list li {
  font-family: var(--font-display);
  font-size: 2.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.summary-card > p.muted {
  font-family: var(--font-display);
  font-size: 1.375rem;
  color: var(--muted);
}

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 42px;
  padding: 9px 18px;
  border: 1.5px solid transparent;
  border-radius: 999px;
  font: inherit;
  font-weight: 650;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 120ms ease, border-color 120ms ease;
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.65;
}

.btn-primary {
  background: var(--accent);
  color: var(--on-accent);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn-secondary {
  background: var(--surface);
  color: var(--ink);
  border-color: var(--control);
}

.btn-secondary:hover:not(:disabled) {
  border-color: var(--ink);
  background: var(--surface-2);
}

.btn-danger {
  background: var(--danger);
  color: var(--on-danger);
}

.btn-danger:hover:not(:disabled) {
  background: var(--danger-hover);
}

.btn-danger-outline {
  background: transparent;
  color: var(--danger);
  border-color: var(--danger);
}

.btn-danger-outline:hover:not(:disabled) {
  background: var(--surface-2);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
}

.btn-ghost:hover {
  background: var(--accent-soft);
}

.btn-small {
  min-height: 34px;
  padding: 5px 14px;
  font-size: 0.9375rem;
}

.btn-wide {
  width: 100%;
}

/* ---------- Forms ---------- */

fieldset {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.field-label {
  padding: 0;
  font-weight: 650;
}

.field-hint {
  color: var(--muted);
  font-size: 0.875rem;
}

.field-error {
  color: var(--danger);
  font-size: 0.9375rem;
  font-weight: 600;
}

.field-error::before {
  /* Decorative: screen readers skip it (the empty text after the slash). */
  content: '⚠ ' / '';
}

.input {
  width: 100%;
  min-height: 44px;
  padding: 9px 14px;
  border: 1.5px solid var(--control);
  border-radius: 12px;
  background: var(--surface);
  color: var(--ink);
  font: inherit;
}

.input::placeholder {
  color: var(--muted);
  opacity: 0.85;
}

.input:hover {
  border-color: var(--ink);
}

.input:focus-visible {
  outline-offset: 1px;
}

.input[aria-invalid='true'] {
  border-color: var(--danger);
  box-shadow: 0 0 0 1px var(--danger);
}

.input[readonly] {
  background: var(--surface-2);
}

.select {
  appearance: auto;
}

.input-short {
  max-width: 120px;
}

.input-money {
  max-width: 170px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.currency-row {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  gap: 8px;
}

.currency-row .select {
  width: auto;
  min-width: 128px;
}

.check {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 36px;
  cursor: pointer;
}

.check input {
  flex: none;
  width: 24px;
  height: 24px;
  margin: 0;
  accent-color: var(--accent);
}

.check-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 4px 16px;
}

.radio-col {
  display: grid;
  gap: 4px;
}

.inline-form {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  gap: 8px 12px;
  margin-top: 18px;
}

.inline-form .field {
  flex: 1 1 240px;
}

.inline-form .btn {
  margin-top: 31px;
}

.card-section {
  padding-top: 22px;
  border-top: 1px solid var(--line);
}

/* Keep a fieldset's heading below the divider, not sitting on it. */
.card-section > legend {
  float: left;
  width: 100%;
  padding: 0;
}

.card-section > legend + * {
  clear: both;
}

.bill-form {
  display: grid;
  gap: 24px;
}

/* Items: a ruled list with column headings on wide screens. */

.item-head {
  display: none;
}

.items {
  list-style: none;
  margin: 0 0 14px;
  padding: 0;
  display: grid;
}

.item-row {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) auto;
  gap: 8px 12px;
  align-items: start;
  padding: 10px 0;
  border-bottom: 1px dashed var(--line);
}

.item-row-itemized {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 2fr) auto;
}

.item-remove {
  min-height: 44px;
}

@media (min-width: 768px) {
  .item-head {
    display: grid;
    grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) auto;
    gap: 12px;
    padding-bottom: 6px;
    color: var(--muted);
    font-size: 0.875rem;
    font-weight: 650;
    border-bottom: 1px solid var(--line);
  }
  .item-head::after {
    content: '';
    width: 92px;
  }
  .item-head-itemized {
    grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 2fr) auto;
  }
  .item-head span:nth-child(2) {
    text-align: right;
  }
  /* The column headings name the fields, so each row's labels are read out but not shown. */
  .item-row .field-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }
  .item-price .input {
    text-align: right;
  }
}

@media (max-width: 767px) {
  .item-row,
  .item-row-itemized {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .item-row .item-name,
  .item-row .item-people {
    grid-column: 1 / -1;
  }
  .item-remove {
    align-self: end;
    justify-self: start;
  }
}

/* Tax, other charges and tip side by side. */

.charges {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
}

.charges .tip-on {
  grid-column: 1 / -1;
}

@media (max-width: 1000px) {
  .charges {
    grid-template-columns: minmax(0, 1fr);
  }
}

.charge-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
}

.charge-row .input-money {
  flex: 1 1 110px;
  max-width: none;
  min-width: 0;
}

.segmented {
  display: inline-flex;
  padding: 3px;
  border: 1.5px solid var(--control);
  border-radius: 999px;
  background: var(--surface);
}

.seg {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 34px;
  min-width: 44px;
  padding: 0 12px;
  border-radius: 999px;
  color: var(--muted);
  font-weight: 650;
  cursor: pointer;
}

.seg input {
  position: absolute;
  inset: 0;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.seg-on {
  background: var(--accent);
  color: var(--on-accent);
}

.seg:has(input:focus-visible) {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

fieldset:disabled .seg {
  cursor: not-allowed;
}

/* People dropdown */

.picker {
  position: relative;
  display: grid;
  gap: 6px;
}

.picker-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  min-height: 44px;
  padding: 9px 14px;
  border: 1.5px solid var(--control);
  border-radius: 12px;
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.picker-button:hover {
  border-color: var(--ink);
}

.picker-empty {
  color: var(--muted);
}

.picker-button[aria-invalid='true'] {
  border-color: var(--danger);
  box-shadow: 0 0 0 1px var(--danger);
}

.picker-caret {
  flex: none;
}

.picker-panel {
  position: absolute;
  top: 50px;
  left: 0;
  right: 0;
  z-index: 10;
  display: grid;
  gap: 8px;
  min-width: 210px;
  padding: 10px 14px 14px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: var(--lift-high);
}

.picker-panel fieldset {
  display: grid;
  max-height: 240px;
  overflow-y: auto;
}

/* ---------- The receipt (results) ---------- */

.receipt-wrap {
  max-width: 560px;
  filter: drop-shadow(0 1px 1px rgba(24, 35, 31, 0.08)) drop-shadow(0 10px 22px rgba(24, 35, 31, 0.1));
}

.receipt {
  --zig: 10px;
  padding: 26px 28px calc(30px + var(--zig));
  background: var(--paper);
  border-radius: 16px 16px 0 0;
  scroll-margin-top: 80px;
  mask: conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) 50% / calc(2 * var(--zig)) 100%;
}

@media (max-width: 767px) {
  .receipt {
    padding: 20px 18px calc(24px + var(--zig));
  }
}

.receipt .section-title {
  padding-bottom: 12px;
  margin-bottom: 14px;
  border-bottom: 2px dashed var(--line);
}

.totals {
  margin: 0;
  display: grid;
  gap: 8px;
}

.totals dt {
  color: var(--muted);
}

.totals dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.totals-grand {
  align-items: baseline;
  margin-top: 6px;
  padding-top: 14px;
  border-top: 2px dashed var(--line);
}

.totals-grand dt {
  color: var(--ink);
  font-weight: 700;
}

.totals-grand dd {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.shares {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.share {
  display: grid;
  gap: 2px;
  padding: 10px 14px;
  border-radius: 12px;
  background: var(--surface-2);
}

.share-main {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-weight: 650;
}

.share-amount {
  font-variant-numeric: tabular-nums;
}

.share-parts {
  font-size: 0.875rem;
}

.badge {
  display: inline-block;
  justify-self: start;
  margin-left: 6px;
  padding: 1px 9px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--ink);
  font-size: 0.8125rem;
  font-weight: 650;
}

.share > .badge {
  margin-left: 0;
}

.badge-muted {
  background: var(--surface-2);
  border: 1px solid var(--line);
}

/* ---------- Lists ---------- */

.link-list,
.balance-list,
.suggest-list,
.member-list,
.activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.link-list.card {
  padding: 8px;
}

