// Temporary: screenshots for the UX review. Not part of the suite.
import { test, expect, type Page } from '@playwright/test';
import { api, makeGroup, signUpFast } from './helpers.js';

const OUT = process.env.SHOTS_DIR as string;
const shot = (page: Page, name: string, full = true) => page.screenshot({ path: `${OUT}/${name}.png`, fullPage: full });

for (const [tag, width] of [['desk', 1280], ['phone', 390]] as const) {
  test(`after ${tag}`, async ({ page }, info) => {
    test.setTimeout(120_000);
    await page.setViewportSize({ width, height: 900 });
    await signUpFast(page, info, 'sana');
    const { groupId, meId, ids } = await makeGroup(page, 'Hunza trip', 'Rs', ['Ali', 'Sara', 'Omar']);
    const { billId } = await api<{ billId: string }>(page, 'post', `/groups/${groupId}/bills`, {
      bill: {
        name: 'Dinner at Cafe Hunza', items: [{ name: 'Chicken karahi', price: '2400' }, { name: 'Naan', price: '300' }, { name: 'Drinks', price: '600' }],
        tax: { mode: 'percent', value: '16' }, otherCharges: { mode: 'amount', value: '250' }, tip: { mode: 'percent', value: '10' }, tipOn: 'items',
        splitMode: 'equal', participantIds: [meId, ids.Ali, ids.Sara, ids.Omar], payerId: meId,
      },
    });

    // New group bill: type two items with Enter, set tax, calculate.
    await page.goto(`/groups/${groupId}/bills/new`);
    await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
    await shot(page, `${tag}-1-group-new-empty`);
    await page.getByLabel('Item 1 name').fill('Chicken karahi');
    await page.keyboard.press('Enter');
    await page.keyboard.type('2400');
    await page.keyboard.press('Enter');
    await page.keyboard.type('Naan');
    await page.keyboard.press('Enter');
    await page.keyboard.type('300');
    await page.getByLabel('Tax percentage').fill('16');
    await page.getByRole('radiogroup', { name: 'Other charges as' }).getByText('Rs').click();
    await page.keyboard.type('250');
    await page.getByRole('button', { name: 'Calculate' }).click();
    await expect(page.getByTestId('grand-total')).toBeVisible();
    await shot(page, `${tag}-2-group-new-calculated`);

    // Split by items.
    await page.getByText('By items', { exact: true }).click();
    await shot(page, `${tag}-3-group-itemized`);

    // Saved bill: read-only receipt.
    await page.goto(`/groups/${groupId}/bills/${billId}`);
    await expect(page.getByRole('heading', { level: 1, name: 'Dinner at Cafe Hunza' })).toBeVisible();
    await shot(page, `${tag}-4-group-bill-view`);

    // Group page: the currency info.
    await page.goto(`/groups/${groupId}`);
    await page.getByRole('button', { name: 'About the currency' }).click();
    await shot(page, `${tag}-5-group-page-currency`, false);

    // Solo: new, with the dropdown close-up.
    await page.goto('/solo/new');
    await expect(page.getByRole('heading', { level: 1, name: 'New solo bill' })).toBeVisible();
    await shot(page, `${tag}-6-solo-new`);
    const box = await page.getByLabel('Currency').boundingBox();
    if (box) await page.screenshot({ path: `${OUT}/${tag}-7-select-closeup.png`, clip: { x: Math.max(0, box.x - 20), y: Math.max(0, box.y - 10), width: Math.min(width - 10, box.width + 60), height: box.height + 20 } });

    // Save a solo bill: back to the list, marked as saved.
    await page.getByLabel('Item 1 name').fill('Coffee');
    await page.getByLabel('Item 1 price').fill('450');
    await page.getByRole('button', { name: 'Save bill' }).click();
    await expect(page.getByRole('heading', { level: 1, name: 'Solo bills' })).toBeVisible();
    await shot(page, `${tag}-8-solo-list-saved`, false);
    await page.getByRole('link', { name: /Coffee|Bill –/ }).first().click();
    await expect(page.getByRole('button', { name: 'Delete' })).toBeVisible();
    await shot(page, `${tag}-9-solo-view`);
    await page.getByRole('link', { name: 'Edit bill' }).click();
    await shot(page, `${tag}-10-solo-edit`);
  });
}
EOF
