 * double-click never saves twice. A handler that navigates away after saving
 * returns 'leaving', and the page stays busy until it's gone.
 */""")
open('client/hooks.ts','w').write(s)

def add_leaving(p, navigate_lines):
    s=open(p).read()
    for line in navigate_lines:
        assert s.count(line)==1, (p, line, s.count(line))
        indent=re.match(r'\s*', line).group(0)
        s=s.replace(line, line+"\n"+indent+"return 'leaving';")
    open(p,'w').write(s)

