import { createPrd, writePrd, readPrd } from '/Users/sanaarshad/.claude/plugins/cache/omc/oh-my-claudecode/5.7.5/dist/hooks/ralph/prd.js';

const dir = '/Users/sanaarshad/Desktop/Sana-Arshad-calculator';
const sid = '47faf5fc-6096-4e68-afab-f042705ddb62';

const stories = [
  {
    id: 'R-01', title: 'Project foundation, database and server',
    description: 'As a Host, I want the app scaffolded with a self-hosted Postgres in Docker Compose, automatic migrations and one Express process serving API + frontend, so that it runs locally and on a server (docs US-30, US-31, US-28).',
    acceptanceCriteria: [
      'package.json has scripts dev, build, start, typecheck, lint, test, test:unit; `npm run build` and `npm run typecheck` exit 0',
      'docker-compose.yml runs postgres:18 with a named volume, port bound to 127.0.0.1 only, and an init script that creates bill_splitter and bill_splitter_test',
      '.env.example holds PORT, DATABASE_URL, TEST_DATABASE_URL, SESSION_SECRET; .env is git-ignored',
      'Server applies versioned SQL migrations automatically at start, recording them in schema_migrations, keeping existing data',
      'With the database unreachable, the server prints exactly "Can\'t reach the database. Start it with: docker compose up -d" and exits non-zero with no stack trace',
      'The production build serves the API under /api and the built React app from one process; config comes only from PORT, DATABASE_URL, SESSION_SECRET',
    ],
  },
  {
    id: 'R-02', title: 'Shared money engine (parsing, validation, calculation, balances, formatting)',
    description: 'As a Solo diner or Group member, I want every amount computed exactly in whole cents with clear validation messages (docs US-05, US-13, US-14, US-15 #3, US-16 #1-#3, US-17 #1-#2, US-25, US-26 #8).',
    acceptanceCriteria: [
      'src/shared has pure TypeScript modules used by both client and server; money math uses integer cents/BigInt, never floats',
      'Unit tests reproduce every numeric example in docs US-05, US-13, US-14, US-16, US-17 and US-25 (#12, #13) and pass',
      'Parsing accepts "1,000.50" and "1000.50" as 100050 cents and rejects "1.000,50", "10,00", "abc", "-5", "1.234", "1000000.01", blank',
      'Validation messages match the docs exactly where the docs quote them (other charges, currency, Add at least one item, Choose who took part, Choose who shared this item, payer, 200 items)',
      'Formatting gives "$1,234,567.50", "Rs 400.00", "CHF 12.00", "kr 30.00"',
      'Suggested payments are the greedy largest-debtor-to-largest-creditor list and balances always sum to 0',
    ],
  },
  {
    id: 'R-03', title: 'Accounts, sessions and privacy',
    description: 'As a Solo diner or Group member, I want an in-app account with a recovery code and private data (docs US-01, US-02, US-03, US-04).',
    acceptanceCriteria: [
      'Sign-up, log-in, log-out and recovery-code reset work through API and UI with the exact messages in docs US-01..US-03',
      'Passwords and recovery codes are stored only as scrypt hashes; sessions are httpOnly SameSite cookies (Secure in production), stored in Postgres, ending on Log out or after 30 days without use',
      'Every bill and group endpoint returns no private data to logged-out users, other accounts, or removed members (API tests)',
    ],
  },
  {
    id: 'R-04', title: 'Solo bills',
    description: 'As a Solo diner, I want to total, save, reopen, edit and delete my own bills (docs US-05..US-08, US-27).',
    acceptanceCriteria: [
      'Solo bill form calculates on Calculate only, hides results on any change, and shows subtotal/tax/other charges/tip/total',
      'Saved solo bills list newest first with name, date, currency and total; default name "Bill – date"; currency locked after first save',
      'Server re-validates and recalculates every save inside one transaction; invalid direct requests are rejected',
      'A failed save keeps all inputs and shows "Couldn\'t save — check your connection" when the server is unreachable',
    ],
  },
  {
    id: 'R-05', title: 'Groups, group bills, balances and settle-ups',
    description: 'As a Group member, I want groups with name-only members, invite codes, equal/itemized bills, a payer, balances, suggestions, settle-ups and an activity log (docs US-09..US-19).',
    acceptanceCriteria: [
      'API + UI cover create group, add member, view/copy invite code, claim name, equal and itemized bills with payer, balances, suggestions, settle-ups, edit/delete, activity log',
      'All limits and messages from docs US-09..US-19 are enforced on the server and shown in the UI',
      'Every group save runs in one transaction with its activity entry',
    ],
  },
  {
    id: 'R-06', title: 'Members leaving, removal, restore, rejoin and group close-out',
    description: 'As a Group member, I want removed members kept on old bills, restorable, able to rejoin with the code, and the last account holder able to close the group (docs US-20..US-24).',
    acceptanceCriteria: [
      'Remove/leave only at balance 0.00 with the exact docs messages; removed members are view-only on old bills ("Restore Omar to change this bill") and lose access',
      'Restore and invite-code rejoin bring back the same member, respecting the 50-member limit',
      'The last member with an account sees the exact warning and leaving permanently deletes the group',
    ],
  },
  {
    id: 'R-07', title: 'App shell, Dashboard, appearance, accessibility and feedback',
    description: 'As a Solo diner or Group member, I want a Dashboard, sidebar/menu navigation, light/dark mode, accessible controls, clear feedback and unsaved-changes warnings (docs US-26, US-33..US-38).',
    acceptanceCriteria: [
      'Dashboard shows per-currency You owe / You\'re owed, groups with my balance, latest solo bills, New solo bill / New group bill buttons, and empty states',
      'Sidebar at 1280 px, menu button at 375 px, no horizontal page scroll from 360 px',
      'Device/Light/Dark appearance saved to the account; toasts, Saving… buttons, skeletons, confirm dialogs with focus trap + Esc, unsaved-changes prompts',
    ],
  },
  {
    id: 'R-08', title: 'One-command test suite',
    description: 'As a Host, I want `npm test` to run unit, API and browser tests (Chromium, Firefox, WebKit) with axe checks against a separate test database (docs US-29, US-32).',
    acceptanceCriteria: [
      '`npm test` checks the database first and stops with the exact "Can\'t reach the database..." message if it is down',
      'API tests and Playwright tests use only bill_splitter_test, which is wiped and rebuilt each run',
      'Playwright runs Chromium, Firefox and WebKit and includes axe WCAG 2.2 AA checks in light and dark mode',
      'With the database running, `npm test` passes twice in a row',
    ],
  },
  {
    id: 'R-09', title: 'README and docs kept current',
    description: 'As a Host and as the project owner, I want the README filled in and every docs story status to reflect what the running app does today, following the saved docs rules.',
    acceptanceCriteria: [
      'README sections What It Is, Who It\'s For, Prerequisites, Installation, Running the App are filled, including the docker compose down -v warning and test instructions',
      'docs/user-stories.md marks a story Implemented only when its criteria are verified by passing tests in the running app; all others stay Not implemented',
      'docs keep the saved templates (roles, jobs, stories, Given/When/Then, status) and an implementation-progress section is kept current',
    ],
  },
];

const prd = createPrd('Bill Splitting Calculator', 'main', 'Implement the bill-splitter spec (.omc/specs/deep-interview-bill-splitter.md v2.6) and keep docs/ statuses current.', stories);
prd.repoQualityClass = 'production';
prd.feedbackCommands = ['npm run typecheck', 'npm run lint', 'npm run test:unit', 'npm run build'];
console.log('written', writePrd(dir, prd, sid));
const back = readPrd(dir, sid);
console.log(back.userStories.map(s => `${s.id} p${s.priority} ${s.passes} ${s.governingCriteriaRevision?.slice(0, 8)}`).join('\n'));

