}

export interface SettleUpSave {
  fromId: string;
  toId: string;
  amount: string;
}

export interface ActivityDto {
  id: string;
  actorName: string;
  message: string;
  at: string;
}

export interface CurrencyTotal {
  currency: string;
  cents: number;
}

export interface DashboardDto {
  owe: CurrencyTotal[];
  owed: CurrencyTotal[];
  groups: GroupSummary[];
  soloBills: SoloBillSummary[];
}

export type JoinResult =
  | { status: 'rejoined'; groupId: string }
  | {
      status: 'choose';
      groupId: string;
      groupName: string;
      choices: { memberId: string; name: string; removed: boolean }[];
    };

