  });
  it('#4 accepts tax/tip % of exactly 0 and 100', () => {
    expect(totals(bill({ tax: pct('0'), tip: pct('100') })).tipCents).toBe(1000);
    expect(totals(bill({ tax: pct('100') })).taxCents).toBe(1000);
