                      <p className="share-parts muted">
                        Food {m(s.foodCents)} · Tax {m(s.taxCents ?? 0)} · Other charges {m(s.otherCents ?? 0)} · Tip {m(s.tipCents ?? 0)}
                      </p>
                    )}
                  </li>
                ))}
              </ul>
            </>
          )}
        </>
      )}
    </section>
  );
});

