input.content:
/* Clean and calm: soft grey page, white rounded cards, one accent colour.
   Every text colour meets 4.5:1 contrast; controls and focus outlines 3:1. */

:root {
  color-scheme: light;
  --bg: #f3f4f6;
  --surface: #ffffff;
  --surface-2: #f7f8fa;
  --text: #1b2330;
  --muted: #555f6d;
  --border: #dde1e7;
  --control-border: #737d8a;
  --accent: #2c56c9;
  --accent-hover: #2348ab;
  --on-accent: #ffffff;
  --accent-soft: #e8eefc;
  --danger: #b42318;
  --danger-hover: #93190f;
  --on-danger: #ffffff;
  --success: #05703f;
  --focus: #2c56c9;
  --skeleton: #e3e6eb;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 1px 3px rgba(16, 24, 40, 0.08);
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    color-scheme: dark;
    --bg: #0f1318;
    --surface: #1a2029;
    --surface-2: #212833;
    --text: #e8ecf1;
    --muted: #a6b0bd;
    --border: #2f3846;
    --control-border: #7d8898;
    --accent: #8fb2ff;
    --accent-hover: #b0c9ff;
    --on-accent: #0f1318;
    --accent-soft: #24304a;
    --danger: #ff9a8f;
    --danger-hover: #ffb8b0;
    --on-danger: #0f1318;
    --success: #74d9a0;
    --focus: #8fb2ff;
    --skeleton: #2a323e;
    --shadow: none;
  }
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #0f1318;
  --surface: #1a2029;
  --surface-2: #212833;
  --text: #e8ecf1;
  --muted: #a6b0bd;
  --border: #2f3846;
  --control-border: #7d8898;
  --accent: #8fb2ff;
  --accent-hover: #b0c9ff;
  --on-accent: #0f1318;
  --accent-soft: #24304a;
  --danger: #ff9a8f;
  --danger-hover: #ffb8b0;
  --on-danger: #0f1318;
  --success: #74d9a0;
  --focus: #8fb2ff;
  --skeleton: #2a323e;
  --shadow: none;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.5;
}

a {
  color: var(--accent);
}

h1,
h2,
h3 {
  line-height: 1.25;
  margin: 0;
}

p {
  margin: 0;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

h1:focus,
main:focus,
.results:focus {
  outline: none;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 16px;
  top: -48px;
  z-index: 50;
  background: var(--surface);
  padding: 8px 12px;
  border-radius: 8px;
}

.skip-link:focus {
  top: 12px;
}

.muted {
  color: var(--muted);
}

.small {
  font-size: 0.875rem;
}

/* ---------- Frame ---------- */

.app {
  min-height: 100vh;
}

.sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: 232px;
  background: var(--surface);
  border-right: 1px solid var(--border);
  padding: 24px 16px;
}

.brand {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.sidebar .brand {
  padding: 0 12px 20px;
}

.brand-large {
  font-size: 1.25rem;
  margin-bottom: 20px;
}

.nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 4px;
}

.nav-link {
  display: block;
  padding: 10px 12px;
  border-radius: 8px;
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
}

.nav-link:hover {
  background: var(--surface-2);
}

.nav-link.active {
  background: var(--accent-soft);
  color: var(--text);
  box-shadow: inset 3px 0 0 var(--accent);
  font-weight: 700;
}

.topbar,
.mobile-nav {
  display: none;
}

.main {
  margin-left: 232px;
  padding: 32px 40px 64px;
  max-width: 1100px;
}

.boot {
  max-width: 480px;
  margin: 15vh auto;
  padding: 0 16px;
}

.public {
  min-height: 100vh;
  display: grid;
  place-items: start center;
  padding: 10vh 16px 32px;
}

.public-card {
  width: 100%;
  max-width: 440px;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  padding: 32px;
}

@media (max-width: 767px) {
  .sidebar {
    display: none;
  }
  .topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    position: sticky;
    top: 0;
    z-index: 20;
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 8px 16px;
  }
  .mobile-nav {
    display: block;
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 8px 16px 12px;
  }
  .main {
    margin-left: 0;
    padding: 20px 16px 48px;
  }
  .public-card {
    padding: 24px 20px;
  }
}

/* ---------- Layout helpers ---------- */

.page-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px 16px;
  margin-bottom: 20px;
}

.page-title {
  font-size: 1.75rem;
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
}

.page-actions,
.row,
.form-actions,
.radio-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
}

.back-link {
  display: inline-block;
  margin-bottom: 6px;
  font-size: 0.9375rem;
  padding: 2px 0;
}

.group-meta {
  margin: -12px 0 16px;
}

.stack {
  display: grid;
  gap: 16px;
}

.stack-lg {
  display: grid;
  gap: 24px;
}

.narrow {
  max-width: 560px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 20px;
}

@media (max-width: 900px) {
  .grid-2 {
    grid-template-columns: minmax(0, 1fr);
  }
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  min-width: 0;
}

@media (max-width: 767px) {
  .card {
    padding: 16px;
  }
}

.card + .card,
form.card + .results {
  margin-top: 20px;
}

.section-title {
  font-size: 1.125rem;
  margin-bottom: 12px;
}

.subsection-title {
  font-size: 1rem;
  margin: 20px 0 8px;
}

.callout {
  background: var(--accent-soft);
  border-radius: var(--radius);
  padding: 14px 18px;
  font-weight: 500;
}

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 40px;
  padding: 8px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}

.btn-primary {
  background: var(--accent);
  color: var(--on-accent);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn-secondary {
  background: var(--surface);
  color: var(--text);
  border-color: var(--control-border);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-2);
}

.btn-danger {
  background: var(--danger);
  color: var(--on-danger);
}

.btn-danger:hover:not(:disabled) {
  background: var(--danger-hover);
}

.btn-danger-outline {
  background: var(--surface);
  color: var(--danger);
  border-color: var(--danger);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  border-color: transparent;
}

.btn-small {
  min-height: 32px;
  padding: 4px 12px;
  font-size: 0.9375rem;
}

.btn-wide {
  width: 100%;
}

/* ---------- Forms ---------- */

fieldset {
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
}

.field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.field-label {
  font-weight: 600;
  padding: 0;
}

.field-hint {
  color: var(--muted);
  font-size: 0.875rem;
}

.field-error {
  color: var(--danger);
  font-size: 0.9375rem;
  font-weight: 500;
}

.field-error::before {
  content: '⚠ ';
}

.input {
  width: 100%;
  min-height: 42px;
  padding: 8px 12px;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
}

.input[aria-invalid='true'] {
  border-color: var(--danger);
  box-shadow: 0 0 0 1px var(--danger);
}

.input[readonly] {
  background: var(--surface-2);
}

.select {
  appearance: auto;
}

.input-short {
  max-width: 120px;
}

.input-money {
  max-width: 180px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.currency-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: start;
}

.currency-row .select {
  width: auto;
  min-width: 120px;
}

.check {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 36px;
  cursor: pointer;
}

.check input {
  width: 24px;
  height: 24px;
  margin: 0;
  accent-color: var(--accent);
  flex: none;
}

.check-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 4px 16px;
}

.radio-col {
  display: grid;
  gap: 4px;
}

.inline-form {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  gap: 8px 12px;
  margin-top: 16px;
}

.inline-form .field {
  flex: 1 1 240px;
}

.inline-form .btn {
  margin-top: 30px;
}

.card-section {
  border-top: 1px solid var(--border);
  padding-top: 16px;
}

.bill-form {
  display: grid;
  gap: 20px;
}

/* Items */

.items {
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
  display: grid;
  gap: 12px;
}

.item-row {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) auto;
  gap: 8px 12px;
  align-items: start;
  padding-bottom: 12px;
  border-bottom: 1px dashed var(--border);
}

.item-row-itemized {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 2fr) auto;
}

.item-remove {
  margin-top: 30px;
}

@media (max-width: 767px) {
  .item-row,
  .item-row-itemized {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .item-row .item-name,
  .item-row .item-people {
    grid-column: 1 / -1;
  }
  .item-remove {
    margin-top: 30px;
    justify-self: start;
  }
}

/* % / amount switch */

.charges {
  display: grid;
  gap: 16px;
}

.charge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-top: 6px;
}

.segmented {
  display: inline-flex;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  overflow: hidden;
}

.seg {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  min-width: 48px;
  justify-content: center;
  padding: 0 14px;
  cursor: pointer;
  font-weight: 600;
}

.seg + .seg {
  border-left: 1px solid var(--control-border);
}

.seg input {
  position: absolute;
  opacity: 0;
  inset: 0;
  margin: 0;
  cursor: pointer;
}

.seg-on {
  background: var(--accent);
  color: var(--on-accent);
}

.seg:has(input:focus-visible) {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

fieldset:disabled .seg {
  cursor: not-allowed;
}

/* People dropdown */

.picker {
  position: relative;
  display: grid;
  gap: 6px;
}

.picker-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  min-height: 42px;
  padding: 8px 12px;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.picker-empty {
  color: var(--muted);
}

.picker-button[aria-invalid='true'] {
  border-color: var(--danger);
  box-shadow: 0 0 0 1px var(--danger);
}

.picker-caret {
  flex: none;
}

.picker-panel {
  position: absolute;
  top: 46px;
  left: 0;
  right: 0;
  z-index: 10;
  min-width: 200px;
  background: var(--surface);
  border: 1px solid var(--control-border);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  padding: 8px 12px 12px;
  display: grid;
  gap: 8px;
}

.picker-panel fieldset {
  display: grid;
  max-height: 240px;
  overflow-y: auto;
}

/* ---------- Results ---------- */

.results {
  scroll-margin-top: 72px;
}

.totals {
  margin: 0;
  display: grid;
  gap: 6px;
  max-width: 420px;
}

.totals > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
}

.totals dt {
  color: var(--muted);
}

.totals dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.totals-grand {
  border-top: 1px solid var(--border);
  padding-top: 8px;
  font-weight: 700;
  font-size: 1.125rem;
}

.totals-grand dt {
  color: var(--text);
}

.shares {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.share {
  display: grid;
  gap: 2px;
  padding: 10px 12px;
  background: var(--surface-2);
  border-radius: 8px;
}

.share-main {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-weight: 600;
}

.share-amount {
  font-variant-numeric: tabular-nums;
}

.share-parts {
  font-size: 0.875rem;
}

.badge {
  justify-self: start;
  display: inline-block;
  margin-left: 6px;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--text);
  font-size: 0.8125rem;
  font-weight: 600;
}

.badge-muted {
  background: var(--surface-2);
  border: 1px solid var(--border);
}

/* ---------- Lists ---------- */

.link-list,
.balance-list,
.suggest-list,
.member-list,
.activity-list,
.summary-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.link-list.card {
  padding: 8px;
}

.link-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  color: var(--text);
  text-decoration: none;
  min-width: 0;
}

.link-row:hover {
  background: var(--surface-2);
}

.link-row-title {
  font-weight: 600;
  min-width: 0;
  overflow-wrap: anywhere;
}

.link-row > span:last-child {
  flex: none;
  font-variant-numeric: tabular-nums;
}

.balance-row,
.suggest-row,
.member-row,
.activity-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 6px 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.balance-row:last-child,
.suggest-row:last-child,
.member-row:last-child,
.activity-row:last-child {
  border-bottom: 0;
}

.summary-list li {
  font-size: 1.375rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.amount-owed {
  color: var(--success);
  font-weight: 600;
}

.amount-owes {
  color: var(--danger);
  font-weight: 600;
}

.amount-settled {
  color: var(--muted);
}

.balance-word {
  font-weight: 500;
}

/* ---------- Tabs ---------- */

.tabs {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  border-bottom: 1px solid var(--border);
  margin-bottom: -1px;
}

.tab {
  min-height: 44px;
  padding: 8px 16px;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: 8px 8px 0 0;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.tab-on {
  background: var(--surface);
  color: var(--text);
  border-color: var(--border);
  box-shadow: inset 0 3px 0 var(--accent);
}

.tab-panel {
  border-top-left-radius: 0;
}

/* ---------- Feedback ---------- */

.alert {
  border-radius: 8px;
  padding: 12px 14px;
  border: 1px solid;
}

.alert-error {
  border-color: var(--danger);
  color: var(--danger);
  background: var(--surface);
  font-weight: 500;
}

.alert-info {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--text);
}

.page-header + .alert,
.alert + form,
.alert + .card {
  margin-bottom: 16px;
}

.toasts {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 100;
  display: grid;
  gap: 8px;
  max-width: calc(100vw - 32px);
}

.toast {
  background: var(--text);
  color: var(--bg);
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  font-weight: 600;
}

.empty {
  display: grid;
  gap: 12px;
  justify-items: start;
  padding: 8px 0;
  color: var(--muted);
}

.skeleton-card {
  display: grid;
  gap: 12px;
  padding: 24px;
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid var(--border);
}

.skeleton-line {
  height: 14px;
  border-radius: 7px;
  background: var(--skeleton);
  animation: pulse 1.4s ease-in-out infinite;
}

@keyframes pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-line {
    animation: none;
  }
  html {
    scroll-behavior: auto;
  }
}

/* Dialog */

.dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  width: min(480px, calc(100vw - 32px));
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.25);
}

.dialog::backdrop {
  background: rgba(15, 19, 24, 0.55);
}

.dialog-title {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.dialog-body {
  margin-bottom: 20px;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

/* Codes */

.recovery-code,
.invite-code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  background: var(--surface-2);
  border: 1px dashed var(--control-border);
  border-radius: 8px;
  padding: 10px 14px;
  overflow-wrap: anywhere;
}

toolu_01Psd8HyfPwmTcNde8XPbyUR.content:
/* Clean and calm: soft grey page, white rounded cards, one accent colour.
   Every text colour meets 4.5:1 contrast; controls and focus outlines 3:1. */

:root {
  color-scheme: light;
  --bg: #f3f4f6;
  --surface: #ffffff;
  --surface-2: #f7f8fa;
  --text: #1b2330;
  --muted: #555f6d;
  --border: #dde1e7;
  --control-border: #737d8a;
  --accent: #2c56c9;
  --accent-hover: #2348ab;
  --on-accent: #ffffff;
  --accent-soft: #e8eefc;
  --danger: #b42318;
  --danger-hover: #93190f;
  --on-danger: #ffffff;
  --success: #05703f;
  --focus: #2c56c9;
  --skeleton: #e3e6eb;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 1px 3px rgba(16, 24, 40, 0.08);
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    color-scheme: dark;
    --bg: #0f1318;
    --surface: #1a2029;
    --surface-2: #212833;
    --text: #e8ecf1;
    --muted: #a6b0bd;
    --border: #2f3846;
    --control-border: #7d8898;
    --accent: #8fb2ff;
    --accent-hover: #b0c9ff;
    --on-accent: #0f1318;
    --accent-soft: #24304a;
    --danger: #ff9a8f;
    --danger-hover: #ffb8b0;
    --on-danger: #0f1318;
    --success: #74d9a0;
    --focus: #8fb2ff;
    --skeleton: #2a323e;
    --shadow: none;
  }
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #0f1318;
  --surface: #1a2029;
  --surface-2: #212833;
  --text: #e8ecf1;
  --muted: #a6b0bd;
  --border: #2f3846;
  --control-border: #7d8898;
  --accent: #8fb2ff;
  --accent-hover: #b0c9ff;
  --on-accent: #0f1318;
  --accent-soft: #24304a;
  --danger: #ff9a8f;
  --danger-hover: #ffb8b0;
  --on-danger: #0f1318;
  --success: #74d9a0;
  --focus: #8fb2ff;
  --skeleton: #2a323e;
  --shadow: none;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.5;
}

a {
  color: var(--accent);
}

h1,
h2,
h3 {
  line-height: 1.25;
  margin: 0;
}

p {
  margin: 0;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

h1:focus,
main:focus,
.results:focus {
  outline: none;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 16px;
  top: -48px;
  z-index: 50;
  background: var(--surface);
  padding: 8px 12px;
  border-radius: 8px;
}

.skip-link:focus {
  top: 12px;
}

.muted {
  color: var(--muted);
}

.small {
  font-size: 0.875rem;
}

/* ---------- Frame ---------- */

.app {
  min-height: 100vh;
}

.sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: 232px;
  background: var(--surface);
  border-right: 1px solid var(--border);
  padding: 24px 16px;
}

.brand {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.sidebar .brand {
  padding: 0 12px 20px;
}

.brand-large {
  font-size: 1.25rem;
  margin-bottom: 20px;
}

.nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 4px;
}

.nav-link {
  display: block;
  padding: 10px 12px;
  border-radius: 8px;
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
}

.nav-link:hover {
  background: var(--surface-2);
}

.nav-link.active {
  background: var(--accent-soft);
  color: var(--text);
  box-shadow: inset 3px 0 0 var(--accent);
  font-weight: 700;
}

.topbar,
.mobile-nav {
  display: none;
}

.main {
  margin-left: 232px;
  padding: 32px 40px 64px;
  max-width: 1100px;
}

.boot {
  max-width: 480px;
  margin: 15vh auto;
  padding: 0 16px;
}

.public {
  min-height: 100vh;
  display: grid;
  place-items: start center;
  padding: 10vh 16px 32px;
}

.public-card {
  width: 100%;
  max-width: 440px;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  padding: 32px;
}

@media (max-width: 767px) {
  .sidebar {
    display: none;
  }
  .topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    position: sticky;
    top: 0;
    z-index: 20;
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 8px 16px;
  }
  .mobile-nav {
    display: block;
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 8px 16px 12px;
  }
  .main {
    margin-left: 0;
    padding: 20px 16px 48px;
  }
  .public-card {
    padding: 24px 20px;
  }
}

/* ---------- Layout helpers ---------- */

.page-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px 16px;
  margin-bottom: 20px;
}

.page-title {
  font-size: 1.75rem;
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
}

.page-actions,
.row,
.form-actions,
.radio-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
}

.back-link {
  display: inline-block;
  margin-bottom: 6px;
  font-size: 0.9375rem;
  padding: 2px 0;
}

.group-meta {
  margin: -12px 0 16px;
}

.stack {
  display: grid;
  gap: 16px;
}

.stack-lg {
  display: grid;
  gap: 24px;
}

.narrow {
  max-width: 560px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 20px;
}

@media (max-width: 900px) {
  .grid-2 {
    grid-template-columns: minmax(0, 1fr);
  }
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  min-width: 0;
}

@media (max-width: 767px) {
  .card {
    padding: 16px;
  }
}

.card + .card,
form.card + .results {
  margin-top: 20px;
}

.section-title {
  font-size: 1.125rem;
  margin-bottom: 12px;
}

.subsection-title {
  font-size: 1rem;
  margin: 20px 0 8px;
}

.callout {
  background: var(--accent-soft);
  border-radius: var(--radius);
  padding: 14px 18px;
  font-weight: 500;
}

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 40px;
  padding: 8px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}

.btn-primary {
  background: var(--accent);
  color: var(--on-accent);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn-secondary {
  background: var(--surface);
  color: var(--text);
  border-color: var(--control-border);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-2);
}

.btn-danger {
  background: var(--danger);
  color: var(--on-danger);
}

.btn-danger:hover:not(:disabled) {
  background: var(--danger-hover);
}

.btn-danger-outline {
  background: var(--surface);
  color: var(--danger);
  border-color: var(--danger);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  border-color: transparent;
}

.btn-small {
  min-height: 32px;
  padding: 4px 12px;
  font-size: 0.9375rem;
}

.btn-wide {
  width: 100%;
}

/* ---------- Forms ---------- */

fieldset {
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
}

.field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.field-label {
  font-weight: 600;
  padding: 0;
}

.field-hint {
  color: var(--muted);
  font-size: 0.875rem;
}

.field-error {
  color: var(--danger);
  font-size: 0.9375rem;
  font-weight: 500;
}

.field-error::before {
  content: '⚠ ';
}

.input {
  width: 100%;
  min-height: 42px;
  padding: 8px 12px;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
}

.input[aria-invalid='true'] {
  border-color: var(--danger);
  box-shadow: 0 0 0 1px var(--danger);
}

.input[readonly] {
  background: var(--surface-2);
}

.select {
  appearance: auto;
}

.input-short {
  max-width: 120px;
}

.input-money {
  max-width: 180px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.currency-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: start;
}

.currency-row .select {
  width: auto;
  min-width: 120px;
}

.check {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 36px;
  cursor: pointer;
}

.check input {
  width: 24px;
  height: 24px;
  margin: 0;
  accent-color: var(--accent);
  flex: none;
}

.check-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 4px 16px;
}

.radio-col {
  display: grid;
  gap: 4px;
}

.inline-form {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  gap: 8px 12px;
  margin-top: 16px;
}

.inline-form .field {
  flex: 1 1 240px;
}

.inline-form .btn {
  margin-top: 30px;
}

.card-section {
  border-top: 1px solid var(--border);
  padding-top: 16px;
}

.bill-form {
  display: grid;
  gap: 20px;
}

/* Items */

.items {
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
  display: grid;
  gap: 12px;
}

.item-row {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) auto;
  gap: 8px 12px;
  align-items: start;
  padding-bottom: 12px;
  border-bottom: 1px dashed var(--border);
}

.item-row-itemized {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 2fr) auto;
}

.item-remove {
  margin-top: 30px;
}

@media (max-width: 767px) {
  .item-row,
  .item-row-itemized {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .item-row .item-name,
  .item-row .item-people {
    grid-column: 1 / -1;
  }
  .item-remove {
    margin-top: 30px;
    justify-self: start;
  }
}

/* % / amount switch */

.charges {
  display: grid;
  gap: 16px;
}

.charge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-top: 6px;
}

.segmented {
  display: inline-flex;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  overflow: hidden;
}

.seg {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  min-width: 48px;
  justify-content: center;
  padding: 0 14px;
  cursor: pointer;
  font-weight: 600;
}

.seg + .seg {
  border-left: 1px solid var(--control-border);
}

.seg input {
  position: absolute;
  opacity: 0;
  inset: 0;
  margin: 0;
  cursor: pointer;
}

.seg-on {
  background: var(--accent);
  color: var(--on-accent);
}

.seg:has(input:focus-visible) {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

fieldset:disabled .seg {
  cursor: not-allowed;
}

/* People dropdown */

.picker {
  position: relative;
  display: grid;
  gap: 6px;
}

.picker-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  min-height: 42px;
  padding: 8px 12px;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.picker-empty {
  color: var(--muted);
}

.picker-button[aria-invalid='true'] {
  border-color: var(--danger);
  box-shadow: 0 0 0 1px var(--danger);
}

.picker-caret {
  flex: none;
}

.picker-panel {
  position: absolute;
  top: 46px;
  left: 0;
  right: 0;
  z-index: 10;
  min-width: 200px;
  background: var(--surface);
  border: 1px solid var(--control-border);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  padding: 8px 12px 12px;
  display: grid;
  gap: 8px;
}

.picker-panel fieldset {
  display: grid;
  max-height: 240px;
  overflow-y: auto;
}

/* ---------- Results ---------- */

.results {
  scroll-margin-top: 72px;
}

.totals {
  margin: 0;
  display: grid;
  gap: 6px;
  max-width: 420px;
}

.totals > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
}

.totals dt {
  color: var(--muted);
}

.totals dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.totals-grand {
  border-top: 1px solid var(--border);
  padding-top: 8px;
  font-weight: 700;
  font-size: 1.125rem;
}

.totals-grand dt {
  color: var(--text);
}

.shares {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.share {
  display: grid;
  gap: 2px;
  padding: 10px 12px;
  background: var(--surface-2);
  border-radius: 8px;
}

.share-main {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-weight: 600;
}

.share-amount {
  font-variant-numeric: tabular-nums;
}

.share-parts {
  font-size: 0.875rem;
}

.badge {
  justify-self: start;
  display: inline-block;
  margin-left: 6px;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--text);
  font-size: 0.8125rem;
  font-weight: 600;
}

.badge-muted {
  background: var(--surface-2);
  border: 1px solid var(--border);
}

/* ---------- Lists ---------- */

.link-list,
.balance-list,
.suggest-list,
.member-list,
.activity-list,
.summary-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.link-list.card {
  padding: 8px;
}

.link-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  color: var(--text);
  text-decoration: none;
  min-width: 0;
}

.link-row:hover {
  background: var(--surface-2);
}

.link-row-title {
  font-weight: 600;
  min-width: 0;
  overflow-wrap: anywhere;
}

.link-row > span:last-child {
  flex: none;
  font-variant-numeric: tabular-nums;
}

.balance-row,
.suggest-row,
.member-row,
.activity-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 6px 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.balance-row:last-child,
.suggest-row:last-child,
.member-row:last-child,
.activity-row:last-child {
  border-bottom: 0;
}

.summary-list li {
  font-size: 1.375rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.amount-owed {
  color: var(--success);
  font-weight: 600;
}

.amount-owes {
  color: var(--danger);
  font-weight: 600;
}

.amount-settled {
  color: var(--muted);
}

.balance-word {
  font-weight: 500;
}

/* ---------- Tabs ---------- */

.tabs {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  border-bottom: 1px solid var(--border);
  margin-bottom: -1px;
}

.tab {
  min-height: 44px;
  padding: 8px 16px;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: 8px 8px 0 0;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.tab-on {
  background: var(--surface);
  color: var(--text);
  border-color: var(--border);
  box-shadow: inset 0 3px 0 var(--accent);
}

.tab-panel {
  border-top-left-radius: 0;
}

/* ---------- Feedback ---------- */

.alert {
  border-radius: 8px;
  padding: 12px 14px;
  border: 1px solid;
}

.alert-error {
  border-color: var(--danger);
  color: var(--danger);
  background: var(--surface);
  font-weight: 500;
}

.alert-info {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--text);
}

.page-header + .alert,
.alert + form,
.alert + .card {
  margin-bottom: 16px;
}

.toasts {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 100;
  display: grid;
  gap: 8px;
  max-width: calc(100vw - 32px);
}

.toast {
  background: var(--text);
  color: var(--bg);
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  font-weight: 600;
}

.empty {
  display: grid;
  gap: 12px;
  justify-items: start;
  padding: 8px 0;
  color: var(--muted);
}

.skeleton-card {
  display: grid;
  gap: 12px;
  padding: 24px;
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid var(--border);
}

.skeleton-line {
  height: 14px;
  border-radius: 7px;
  background: var(--skeleton);
  animation: pulse 1.4s ease-in-out infinite;
}

@keyframes pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-line {
    animation: none;
  }
  html {
    scroll-behavior: auto;
  }
}

/* Dialog */

.dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  width: min(480px, calc(100vw - 32px));
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.25);
}

.dialog::backdrop {
  background: rgba(15, 19, 24, 0.55);
}

.dialog-title {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.dialog-body {
  margin-bottom: 20px;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

/* Codes */

.recovery-code,
.invite-code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  background: var(--surface-2);
  border: 1px dashed var(--control-border);
  border-radius: 8px;
  padding: 10px 14px;
  overflow-wrap: anywhere;
}

toolUseResult.content:
/* Clean and calm: soft grey page, white rounded cards, one accent colour.
   Every text colour meets 4.5:1 contrast; controls and focus outlines 3:1. */

:root {
  color-scheme: light;
  --bg: #f3f4f6;
  --surface: #ffffff;
  --surface-2: #f7f8fa;
  --text: #1b2330;
  --muted: #555f6d;
  --border: #dde1e7;
  --control-border: #737d8a;
  --accent: #2c56c9;
  --accent-hover: #2348ab;
  --on-accent: #ffffff;
  --accent-soft: #e8eefc;
  --danger: #b42318;
  --danger-hover: #93190f;
  --on-danger: #ffffff;
  --success: #05703f;
  --focus: #2c56c9;
  --skeleton: #e3e6eb;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 1px 3px rgba(16, 24, 40, 0.08);
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    color-scheme: dark;
    --bg: #0f1318;
    --surface: #1a2029;
    --surface-2: #212833;
    --text: #e8ecf1;
    --muted: #a6b0bd;
    --border: #2f3846;
    --control-border: #7d8898;
    --accent: #8fb2ff;
    --accent-hover: #b0c9ff;
    --on-accent: #0f1318;
    --accent-soft: #24304a;
    --danger: #ff9a8f;
    --danger-hover: #ffb8b0;
    --on-danger: #0f1318;
    --success: #74d9a0;
    --focus: #8fb2ff;
    --skeleton: #2a323e;
    --shadow: none;
  }
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #0f1318;
  --surface: #1a2029;
  --surface-2: #212833;
  --text: #e8ecf1;
  --muted: #a6b0bd;
  --border: #2f3846;
  --control-border: #7d8898;
  --accent: #8fb2ff;
  --accent-hover: #b0c9ff;
  --on-accent: #0f1318;
  --accent-soft: #24304a;
  --danger: #ff9a8f;
  --danger-hover: #ffb8b0;
  --on-danger: #0f1318;
  --success: #74d9a0;
  --focus: #8fb2ff;
  --skeleton: #2a323e;
  --shadow: none;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.5;
}

a {
  color: var(--accent);
}

h1,
h2,
h3 {
  line-height: 1.25;
  margin: 0;
}

p {
  margin: 0;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

h1:focus,
main:focus,
.results:focus {
  outline: none;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 16px;
  top: -48px;
  z-index: 50;
  background: var(--surface);
  padding: 8px 12px;
  border-radius: 8px;
}

.skip-link:focus {
  top: 12px;
}

.muted {
  color: var(--muted);
}

.small {
  font-size: 0.875rem;
}

/* ---------- Frame ---------- */

.app {
  min-height: 100vh;
}

.sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: 232px;
  background: var(--surface);
  border-right: 1px solid var(--border);
  padding: 24px 16px;
}

.brand {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.sidebar .brand {
  padding: 0 12px 20px;
}

.brand-large {
  font-size: 1.25rem;
  margin-bottom: 20px;
}

.nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 4px;
}

.nav-link {
  display: block;
  padding: 10px 12px;
  border-radius: 8px;
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
}

.nav-link:hover {
  background: var(--surface-2);
}

.nav-link.active {
  background: var(--accent-soft);
  color: var(--text);
  box-shadow: inset 3px 0 0 var(--accent);
  font-weight: 700;
}

.topbar,
.mobile-nav {
  display: none;
}

.main {
  margin-left: 232px;
  padding: 32px 40px 64px;
  max-width: 1100px;
}

.boot {
  max-width: 480px;
  margin: 15vh auto;
  padding: 0 16px;
}

.public {
  min-height: 100vh;
  display: grid;
  place-items: start center;
  padding: 10vh 16px 32px;
}

.public-card {
  width: 100%;
  max-width: 440px;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  padding: 32px;
}

@media (max-width: 767px) {
  .sidebar {
    display: none;
  }
  .topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    position: sticky;
    top: 0;
    z-index: 20;
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 8px 16px;
  }
  .mobile-nav {
    display: block;
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 8px 16px 12px;
  }
  .main {
    margin-left: 0;
    padding: 20px 16px 48px;
  }
  .public-card {
    padding: 24px 20px;
  }
}

/* ---------- Layout helpers ---------- */

.page-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px 16px;
  margin-bottom: 20px;
}

.page-title {
  font-size: 1.75rem;
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
}

.page-actions,
.row,
.form-actions,
.radio-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
}

.back-link {
  display: inline-block;
  margin-bottom: 6px;
  font-size: 0.9375rem;
  padding: 2px 0;
}

.group-meta {
  margin: -12px 0 16px;
}

.stack {
  display: grid;
  gap: 16px;
}

.stack-lg {
  display: grid;
  gap: 24px;
}

.narrow {
  max-width: 560px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 20px;
}

@media (max-width: 900px) {
  .grid-2 {
    grid-template-columns: minmax(0, 1fr);
  }
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  min-width: 0;
}

@media (max-width: 767px) {
  .card {
    padding: 16px;
  }
}

.card + .card,
form.card + .results {
  margin-top: 20px;
}

.section-title {
  font-size: 1.125rem;
  margin-bottom: 12px;
}

.subsection-title {
  font-size: 1rem;
  margin: 20px 0 8px;
}

.callout {
  background: var(--accent-soft);
  border-radius: var(--radius);
  padding: 14px 18px;
  font-weight: 500;
}

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 40px;
  padding: 8px 16px;
  border-radius: 8px;
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.7;
}

.btn-primary {
  background: var(--accent);
  color: var(--on-accent);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn-secondary {
  background: var(--surface);
  color: var(--text);
  border-color: var(--control-border);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-2);
}

.btn-danger {
  background: var(--danger);
  color: var(--on-danger);
}

.btn-danger:hover:not(:disabled) {
  background: var(--danger-hover);
}

.btn-danger-outline {
  background: var(--surface);
  color: var(--danger);
  border-color: var(--danger);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  border-color: transparent;
}

.btn-small {
  min-height: 32px;
  padding: 4px 12px;
  font-size: 0.9375rem;
}

.btn-wide {
  width: 100%;
}

/* ---------- Forms ---------- */

fieldset {
  border: 0;
  margin: 0;
  padding: 0;
  min-width: 0;
}

.field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.field-label {
  font-weight: 600;
  padding: 0;
}

.field-hint {
  color: var(--muted);
  font-size: 0.875rem;
}

.field-error {
  color: var(--danger);
  font-size: 0.9375rem;
  font-weight: 500;
}

.field-error::before {
  content: '⚠ ';
}

.input {
  width: 100%;
  min-height: 42px;
  padding: 8px 12px;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
}

.input[aria-invalid='true'] {
  border-color: var(--danger);
  box-shadow: 0 0 0 1px var(--danger);
}

.input[readonly] {
  background: var(--surface-2);
}

.select {
  appearance: auto;
}

.input-short {
  max-width: 120px;
}

.input-money {
  max-width: 180px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.currency-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: start;
}

.currency-row .select {
  width: auto;
  min-width: 120px;
}

.check {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 36px;
  cursor: pointer;
}

.check input {
  width: 24px;
  height: 24px;
  margin: 0;
  accent-color: var(--accent);
  flex: none;
}

.check-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 4px 16px;
}

.radio-col {
  display: grid;
  gap: 4px;
}

.inline-form {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  gap: 8px 12px;
  margin-top: 16px;
}

.inline-form .field {
  flex: 1 1 240px;
}

.inline-form .btn {
  margin-top: 30px;
}

.card-section {
  border-top: 1px solid var(--border);
  padding-top: 16px;
}

.bill-form {
  display: grid;
  gap: 20px;
}

/* Items */

.items {
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
  display: grid;
  gap: 12px;
}

.item-row {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) auto;
  gap: 8px 12px;
  align-items: start;
  padding-bottom: 12px;
  border-bottom: 1px dashed var(--border);
}

.item-row-itemized {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 2fr) auto;
}

.item-remove {
  margin-top: 30px;
}

@media (max-width: 767px) {
  .item-row,
  .item-row-itemized {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .item-row .item-name,
  .item-row .item-people {
    grid-column: 1 / -1;
  }
  .item-remove {
    margin-top: 30px;
    justify-self: start;
  }
}

/* % / amount switch */

.charges {
  display: grid;
  gap: 16px;
}

.charge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-top: 6px;
}

.segmented {
  display: inline-flex;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  overflow: hidden;
}

.seg {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  min-width: 48px;
  justify-content: center;
  padding: 0 14px;
  cursor: pointer;
  font-weight: 600;
}

.seg + .seg {
  border-left: 1px solid var(--control-border);
}

.seg input {
  position: absolute;
  opacity: 0;
  inset: 0;
  margin: 0;
  cursor: pointer;
}

.seg-on {
  background: var(--accent);
  color: var(--on-accent);
}

.seg:has(input:focus-visible) {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

fieldset:disabled .seg {
  cursor: not-allowed;
}

/* People dropdown */

.picker {
  position: relative;
  display: grid;
  gap: 6px;
}

.picker-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  min-height: 42px;
  padding: 8px 12px;
  border: 1px solid var(--control-border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.picker-empty {
  color: var(--muted);
}

.picker-button[aria-invalid='true'] {
  border-color: var(--danger);
  box-shadow: 0 0 0 1px var(--danger);
}

.picker-caret {
  flex: none;
}

.picker-panel {
  position: absolute;
  top: 46px;
  left: 0;
  right: 0;
  z-index: 10;
  min-width: 200px;
  background: var(--surface);
  border: 1px solid var(--control-border);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  padding: 8px 12px 12px;
  display: grid;
  gap: 8px;
}

.picker-panel fieldset {
  display: grid;
  max-height: 240px;
  overflow-y: auto;
}

/* ---------- Results ---------- */

.results {
  scroll-margin-top: 72px;
}

.totals {
  margin: 0;
  display: grid;
  gap: 6px;
  max-width: 420px;
}

.totals > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
}

.totals dt {
  color: var(--muted);
}

.totals dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.totals-grand {
  border-top: 1px solid var(--border);
  padding-top: 8px;
  font-weight: 700;
  font-size: 1.125rem;
}

.totals-grand dt {
  color: var(--text);
}

.shares {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.share {
  display: grid;
  gap: 2px;
  padding: 10px 12px;
  background: var(--surface-2);
  border-radius: 8px;
}

.share-main {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-weight: 600;
}

.share-amount {
  font-variant-numeric: tabular-nums;
}

.share-parts {
  font-size: 0.875rem;
}

.badge {
  justify-self: start;
  display: inline-block;
  margin-left: 6px;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--text);
  font-size: 0.8125rem;
  font-weight: 600;
}

.badge-muted {
  background: var(--surface-2);
  border: 1px solid var(--border);
}

/* ---------- Lists ---------- */

.link-list,
.balance-list,
.suggest-list,
.member-list,
.activity-list,
.summary-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.link-list.card {
  padding: 8px;
}

.link-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  color: var(--text);
  text-decoration: none;
  min-width: 0;
}

.link-row:hover {
  background: var(--surface-2);
}

.link-row-title {
  font-weight: 600;
  min-width: 0;
  overflow-wrap: anywhere;
}

.link-row > span:last-child {
  flex: none;
  font-variant-numeric: tabular-nums;
}

.balance-row,
.suggest-row,
.member-row,
.activity-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 6px 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.balance-row:last-child,
.suggest-row:last-child,
.member-row:last-child,
.activity-row:last-child {
  border-bottom: 0;
}

.summary-list li {
  font-size: 1.375rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.amount-owed {
  color: var(--success);
  font-weight: 600;
}

.amount-owes {
  color: var(--danger);
  font-weight: 600;
}

.amount-settled {
  color: var(--muted);
}

.balance-word {
  font-weight: 500;
}

/* ---------- Tabs ---------- */

.tabs {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  border-bottom: 1px solid var(--border);
  margin-bottom: -1px;
}

.tab {
  min-height: 44px;
  padding: 8px 16px;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: 8px 8px 0 0;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.tab-on {
  background: var(--surface);
  color: var(--text);
  border-color: var(--border);
  box-shadow: inset 0 3px 0 var(--accent);
}

.tab-panel {
  border-top-left-radius: 0;
}

/* ---------- Feedback ---------- */

.alert {
  border-radius: 8px;
  padding: 12px 14px;
  border: 1px solid;
}

.alert-error {
  border-color: var(--danger);
  color: var(--danger);
  background: var(--surface);
  font-weight: 500;
}

.alert-info {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--text);
}

.page-header + .alert,
.alert + form,
.alert + .card {
  margin-bottom: 16px;
}

.toasts {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 100;
  display: grid;
  gap: 8px;
  max-width: calc(100vw - 32px);
}

.toast {
  background: var(--text);
  color: var(--bg);
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  font-weight: 600;
}

.empty {
  display: grid;
  gap: 12px;
  justify-items: start;
  padding: 8px 0;
  color: var(--muted);
}

.skeleton-card {
  display: grid;
  gap: 12px;
  padding: 24px;
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid var(--border);
}

.skeleton-line {
  height: 14px;
  border-radius: 7px;
  background: var(--skeleton);
  animation: pulse 1.4s ease-in-out infinite;
}

@keyframes pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-line {
    animation: none;
  }
  html {
    scroll-behavior: auto;
  }
}

/* Dialog */

.dialog {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  width: min(480px, calc(100vw - 32px));
  background: var(--surface);
  color: var(--text);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.25);
}

.dialog::backdrop {
  background: rgba(15, 19, 24, 0.55);
}

.dialog-title {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.dialog-body {
  margin-bottom: 20px;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

/* Codes */

