describe('A: at most a few password checks at once', () => {
  it('runs at most 4 at a time and turns away the overflow', async () => {
    const run = createLimiter(4, 2);
    let active = 0;
    let peak = 0;
    const task = () =>
      new Promise<void>((resolve) => {
        active += 1;
        peak = Math.max(peak, active);
        setTimeout(() => {
          active -= 1;
          resolve();
