import { useState, type FormEvent } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import type { Account, InviteInfo, InviteResult } from '../../shared/api.js';
import { checkPassword, checkUsername } from '../../shared/rules.js';
import { ApiError, api } from '../api.js';
import { useBusy, useLoad } from '../hooks.js';
import { useSession } from '../session.js';
import { useToast } from '../components/Toasts.js';
import { Logo } from '../components/Layout.js';
import { Alert, PasswordField, Skeleton, TextField, usePageTitle } from '../components/ui.js';

function joinedMessage(result: InviteResult | null | undefined): string {
  if (!result) return '';
  const n = result.joined.length;
  return n === 0 ? 'Your account is linked' : `You joined ${n} group${n === 1 ? '' : 's'}`;
}

/**
 * A personal invite link: /invite/<code>. Logged out, the person creates an
 * account or logs in; logged in, one button joins. Either way every group the
 * person is in is linked at once. Nobody picks a name from a list.
 */
export function InvitePage() {
  const { code = '' } = useParams();
  const navigate = useNavigate();
  const toast = useToast();
  const { account, setAccount, recoveryCode, setRecoveryCode } = useSession();
  const { data, error, loading } = useLoad(() => api.get<{ invite: InviteInfo }>(`/invites/${code}`).then((r) => r.invite), [code]);
  usePageTitle(data ? `Invite for ${data.name}` : 'Invite');
  const [mode, setMode] = useState<'signup' | 'login'>('signup');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [fields, setFields] = useState<Record<string, string>>({});
  const [formError, setFormError] = useState('');
  const [pendingResult, setPendingResult] = useState<InviteResult | null>(null);
  const { busy, run } = useBusy();

  const finish = (result: InviteResult | null) => {
    toast(joinedMessage(result));
    navigate('/', { replace: true });
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setFormError('');
    if (mode === 'signup') {
      const u = checkUsername(username);
      const p = checkPassword(password);
      const local: Record<string, string> = {};
      if (!u.ok) local.username = u.message;
      if (!p.ok) local.password = p.message;
      setFields(local);
      if (!u.ok || !p.ok) return;
    }
    void run(async () => {
      try {
        if (mode === 'signup') {
          const r = await api.post<{ account: Account; recoveryCode: string; invite: InviteResult | null }>('/auth/signup', {
            username,
            password,
            inviteCode: code,
          });
          // Show the recovery code first; the groups are already linked.
          setPendingResult(r.invite);
          setRecoveryCode(r.recoveryCode);
          setAccount(r.account);
        } else {
          const r = await api.post<{ account: Account; invite: InviteResult | null }>('/auth/login', { username, password, inviteCode: code });
          setAccount(r.account);
          finish(r.invite);
        }
      } catch (err) {
        const apiErr = err as ApiError;
        setFields(apiErr.fields);
        if (!Object.keys(apiErr.fields).length || apiErr.fields.inviteCode) setFormError(apiErr.message);
      }
    });
  };

  const acceptAsMe = () =>
    run(async () => {
      try {
        const r = await api.post<{ result: InviteResult }>(`/invites/${code}/accept`);
        finish(r.result);
      } catch (err) {
        setFormError((err as ApiError).message);
      }
    });

  let body;
  if (loading) {
    body = <Skeleton lines={4} />;
  } else if (error || !data) {
    body = (
      <div className="stack">
        <h1 tabIndex={-1} className="page-title">
          Invite not found
        </h1>
        <Alert>{error?.message}</Alert>
        <p className="muted">
          <Link to="/">Go to Bill Splitter</Link>
        </p>
      </div>
    );
  } else if (account && recoveryCode) {
    body = (
      <div className="stack">
        <h1 tabIndex={-1} className="page-title">
          Save your recovery code
        </h1>
        <Alert tone="info">
          <strong>Save this now.</strong> It's the only way to reset your password if you forget it, and it will never be shown again.
        </Alert>
        <p className="recovery-code" data-testid="recovery-code">
          {recoveryCode}
        </p>
        <button
          type="button"
          className="btn btn-primary"
          onClick={() => {
            setRecoveryCode(null);
            finish(pendingResult);
          }}
        >
          I've saved it, continue
        </button>
      </div>
    );
  } else {
    body = (
      <div className="stack">
        <h1 tabIndex={-1} className="page-title">
          {data.name}, join your friends' groups
        </h1>
        {data.groups.length > 0 && (
          <div>
            <p className="muted">You're in:</p>
            <ul className="invite-groups">
              {data.groups.map((g) => (
                <li key={g}>{g}</li>
              ))}
            </ul>
          </div>
        )}
        {data.used ? (
          <Alert>This invite has already been used</Alert>
        ) : account ? (
          <>
            <Alert>{formError}</Alert>
            <p>
              You're logged in as <strong>{account.username}</strong>. Joining links these groups to this account.
            </p>
            <button type="button" className="btn btn-primary btn-wide" onClick={() => void acceptAsMe()} disabled={busy}>
              {busy ? 'Joining…' : 'Join these groups'}
            </button>
          </>
        ) : (
          <form className="stack" onSubmit={submit} noValidate>
            <div className="segmented segmented-wide" role="radiogroup" aria-label="Do you have an account?">
              <label className={mode === 'signup' ? 'seg seg-on' : 'seg'}>
                <input type="radio" name="invite-mode" checked={mode === 'signup'} onChange={() => setMode('signup')} />
                <span>I'm new here</span>
              </label>
              <label className={mode === 'login' ? 'seg seg-on' : 'seg'}>
                <input type="radio" name="invite-mode" checked={mode === 'login'} onChange={() => setMode('login')} />
                <span>I have an account</span>
              </label>
            </div>
            <Alert>{formError}</Alert>
            <TextField
              label="Username"
              hint={mode === 'signup' ? '3–30 characters: letters, numbers and _' : undefined}
              value={username}
              onChange={setUsername}
              error={fields.username}
              autoComplete="username"
              autoCapitalize="none"
            />
            <PasswordField
              label="Password"
              hint={mode === 'signup' ? 'At least 8 characters' : undefined}
              value={password}
              onChange={setPassword}
              error={fields.password}
              autoComplete={mode === 'signup' ? 'new-password' : 'current-password'}
            />
            <button type="submit" className="btn btn-primary btn-wide" disabled={busy}>
              {busy ? 'Joining…' : mode === 'signup' ? 'Create account and join' : 'Log in and join'}
            </button>
          </form>
        )}
      </div>
    );
  }

  return (
    <main id="main" className="public public-single">
      <div className="public-card">
        <div className="brand">
          <Logo />
          <span>Bill Splitter</span>
        </div>
        {body}
      </div>
    </main>
  );
}
