// The bill form's Calculate step: spare empty item lines are left out, and
// messages about items still point at the right line on the form.
import { describe, expect, it } from 'vitest';
import { MESSAGES } from '../../shared/rules.js';
import { calculate, emptyBill, newItem, toBillInput, toFormErrors } from '../../client/billEditor.js';

const bill = (items: { name: string; price: string }[]) => emptyBill({ items: items.map((it) => newItem(it)) });

describe('US-05 #16 empty item lines', () => {
  it('a line with no name and no price is left out of the total and of what is saved', () => {
    const state = bill([
      { name: 'Coffee', price: '4.50' },
      { name: '', price: '' },
      { name: 'Tea', price: '3.00' },
      { name: '  ', price: ' ' },
    ]);
    const outcome = calculate(state, 'solo', false);
    expect(outcome.ok && outcome.result.totals.itemsCents).toBe(750);
    expect(toBillInput(state).items).toEqual([
      { name: 'Coffee', price: '4.50' },
      { name: 'Tea', price: '3.00' },
    ]);
  });

  it('a message about an item stays next to that item, even after a skipped line', () => {
    const state = bill([
      { name: '', price: '' },
      { name: 'Tea', price: '' },
      { name: '', price: 'abc' },
    ]);
    const outcome = calculate(state, 'solo', false);
    expect(outcome.ok).toBe(false);
    if (!outcome.ok) {
      expect(outcome.errors).toMatchObject({ 'items.1.price': MESSAGES.price, 'items.2.price': MESSAGES.price });
      expect(outcome.errors).not.toHaveProperty('items.0.price');
    }
  });

  it('only empty lines means no items', () => {
    const outcome = calculate(bill([{ name: '', price: '' }]), 'solo', false);
    expect(!outcome.ok && outcome.errors.items).toBe(MESSAGES.noItems);
  });

  it("the server's item messages are mapped the same way", () => {
    const state = bill([
      { name: '', price: '' },
      { name: 'Tea', price: '3' },
    ]);
    expect(toFormErrors(state, { 'items.0.price': 'x', name: 'y' })).toEqual({ 'items.1.price': 'x', name: 'y' });
  });
});

import { useId, useMemo, useRef, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import type { FieldErrors } from '../../shared/bill.js';
import type { SoloBillDetail, SoloBillSummary } from '../../shared/api.js';
import { parseHundredths } from '../../shared/money.js';
import { ApiError, api } from '../api.js';
import { calculate, chosenCurrency, emptyBill, focusFirstError, fromInput, rateLabels, revealResults, stripKeys, toFormErrors, toBillInput, type BillFormState, type CalcResult } from '../billEditor.js';
import { clearFieldError, withoutKey } from '../fieldErrors.js';
import { useBusy, useFocusFirstError, useLoad, useSavedBillId } from '../hooks.js';
import { BillForm } from '../components/BillForm.js';
import { ConfirmDialog } from '../components/ConfirmDialog.js';
import { CurrencyPicker } from '../components/CurrencyPicker.js';
import { Results } from '../components/Results.js';
import { useToast } from '../components/Toasts.js';
import { useUnsavedGuard } from '../components/UnsavedGuard.js';
import { Alert, EmptyState, PageHeader, Skeleton, money, niceDate, usePageTitle } from '../components/ui.js';

export function SoloListPage() {
  usePageTitle('Solo bills');
  const savedId = useSavedBillId();
  const { data, error, loading } = useLoad(() => api.get<{ bills: SoloBillSummary[] }>('/solo-bills'), []);
  return (
    <>
      <PageHeader title="Solo bills">
        <Link className="btn btn-primary" to="/solo/new">
          New solo bill
        </Link>
      </PageHeader>
      <Alert>{error?.message}</Alert>
      {loading && <Skeleton lines={4} />}
      {data &&
        (data.bills.length === 0 ? (
          <div className="card">
            <EmptyState text="No solo bills yet. Total your first bill to keep a record of it." action={{ to: '/solo/new', label: 'New solo bill' }} />
          </div>
        ) : (
          <ul className="link-list card">
            {data.bills.map((b) => (
              <li key={b.id}>
                <Link to={`/solo/${b.id}`} className={b.id === savedId ? 'link-row link-row-saved' : 'link-row'}>
                  <span className="link-row-title">
                    {b.name}
                    {b.id === savedId && <span className="badge badge-saved">Saved</span>}
                    <span className="muted small"> · {niceDate(b.date)} · {b.currency}</span>
                  </span>
                  <span>{money(b.totalCents, b.currency)}</span>
                </Link>
              </li>
            ))}
          </ul>
        ))}
    </>
  );
}

/** A saved solo bill, read-only: the receipt with its items, plus Edit and Delete. */
export function SoloBillViewPage() {
  const { id } = useParams();
  const { data, error, loading } = useLoad(() => api.get<{ bill: SoloBillDetail }>(`/solo-bills/${id}`).then((r) => r.bill), [id]);
  usePageTitle(data?.name ?? 'Solo bill');
  if (loading) return <Skeleton lines={6} />;
  if (error || !data) {
    return (
      <>
        <PageHeader title="Solo bill" back={{ to: '/solo', label: 'Solo bills' }} />
        <Alert>{error?.message}</Alert>
      </>
    );
  }
  return <SoloBillView bill={data} />;
}

function SoloBillView({ bill }: { bill: SoloBillDetail }) {
  const navigate = useNavigate();
  const toast = useToast();
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [headerError, setHeaderError] = useState('');
  const { busy, run } = useBusy();
  const items = bill.input.items.map((it, i) => ({ name: it.name || `Item ${i + 1}`, cents: parseHundredths(it.price) }));

  const onDelete = () =>
    run(async () => {
      setHeaderError('');
      try {
        await api.del(`/solo-bills/${bill.id}`);
        setConfirmDelete(false);
        toast('Bill deleted');
        navigate('/solo', { replace: true });
      } catch (err) {
        setConfirmDelete(false);
        setHeaderError((err as ApiError).message);
      }
    });

  return (
    <>
      <PageHeader title={bill.name} back={{ to: '/solo', label: 'Solo bills' }}>
        <Link className="btn btn-primary" to={`/solo/${bill.id}/edit`}>
          Edit bill
        </Link>
        <button type="button" className="btn btn-danger-outline" onClick={() => setConfirmDelete(true)}>
          Delete
        </button>
      </PageHeader>
      <Alert>{headerError}</Alert>
      <p className="bill-summary">
        Bill from {niceDate(bill.date)}. Amounts in {bill.currency}.
      </p>
      <Results
        result={{ totals: bill.totals, shares: null }}
        currency={bill.currency}
        rates={rateLabels(fromInput(bill.input))}
        title="Bill"
        items={items}
      />
      <ConfirmDialog
        open={confirmDelete}
        title="Delete this bill?"
        confirmLabel="Delete bill"
        danger
        busy={busy}
        onConfirm={() => void onDelete()}
        onCancel={() => setConfirmDelete(false)}
      >
        <p>It will be removed from your history for good.</p>
      </ConfirmDialog>
    </>
  );
}

/** A new solo bill (no id), or a saved one being edited (/solo/:id/edit). */
export function SoloBillPage() {
  const { id } = useParams();
  const isNew = id === undefined;
  const { data, error, loading } = useLoad(
    () => (isNew ? Promise.resolve(null) : api.get<{ bill: SoloBillDetail }>(`/solo-bills/${id}`).then((r) => r.bill)),
    [id],
  );
  usePageTitle(isNew ? 'New solo bill' : data ? `Edit ${data.name}` : 'Edit solo bill');

  if (loading) return <Skeleton lines={6} />;
  if (error) {
    return (
      <>
        <PageHeader title="Solo bill" back={{ to: '/solo', label: 'Solo bills' }} />
        <Alert>{error.message}</Alert>
      </>
    );
  }
  return <SoloBillEditor key={id ?? 'new'} saved={data} />;
}

function SoloBillEditor({ saved }: { saved: SoloBillDetail | null }) {
  const navigate = useNavigate();
  const toast = useToast();
  const formId = useId();
  const initial = useMemo(() => (saved ? fromInput(saved.input, saved.currency) : emptyBill()), [saved]);
  const [state, setState] = useState<BillFormState>(initial);
  const [snapshot] = useState(() => JSON.stringify(stripKeys(initial)));
  const [errors, setErrors] = useState<FieldErrors>({});
  const [result, setResult] = useState<CalcResult | null>(saved ? { totals: saved.totals, shares: null } : null);
  const [pageError, setPageError] = useState('');
  const { busy, run } = useBusy();
  const formRef = useRef<HTMLFormElement>(null);
  const resultsRef = useRef<HTMLElement>(null);
  const focusErrors = useFocusFirstError(formRef);
  const guard = useUnsavedGuard(JSON.stringify(stripKeys(state)) !== snapshot);
  const currency = saved ? saved.currency : chosenCurrency(state);
  const viewPath = saved ? `/solo/${saved.id}` : '/solo';

  const change = (next: BillFormState) => {
    setState(next);
    setResult(null); // any change hides the old result
  };

  const onCalculate = () => {
    const outcome = calculate(state, 'solo', !saved);
    if (!outcome.ok) {
      setErrors(outcome.errors);
      setResult(null);
      window.setTimeout(() => focusFirstError(formRef.current), 0);
      return;
    }
    setErrors({});
    setResult(outcome.result);
    revealResults(resultsRef.current);
  };

  const onSave = () =>
    run(async () => {
      setPageError('');
      const outcome = calculate(state, 'solo', !saved);
      if (!outcome.ok) {
        setErrors(outcome.errors);
        window.setTimeout(() => focusFirstError(formRef.current), 0);
        return;
      }
      setErrors({});
      try {
        const body = { currency: chosenCurrency(state), bill: toBillInput(state) };
        const r = saved
          ? await api.put<{ bill: SoloBillSummary }>(`/solo-bills/${saved.id}`, body)
          : await api.post<{ bill: SoloBillSummary }>('/solo-bills', body);
        toast('Bill saved');
        guard.allowLeave();
        // Back to where the bill is listed, with it marked as just saved.
        navigate('/solo', { replace: true, state: { savedBillId: r.bill.id } });
      } catch (err) {
        const e = err as ApiError;
        setErrors(toFormErrors(state, e.fields));
        setPageError(e.message);
        if (Object.keys(e.fields).length) focusErrors();
      }
    });

  return (
    <>
      <PageHeader title={saved ? `Edit ${saved.name}` : 'New solo bill'} back={saved ? { to: viewPath, label: saved.name } : { to: '/solo', label: 'Solo bills' }}>
        {saved && (
          <Link className="btn btn-secondary" to={viewPath}>
            Cancel
          </Link>
        )}
      </PageHeader>
      <div className="bill-layout">
        <form
          id={formId}
          ref={formRef}
          className="card stack bill-card"
          noValidate
          onSubmit={(e) => {
            e.preventDefault();
            onCalculate();
          }}
        >
          {saved ? (
            <div className="field">
              <span className="field-label">Currency</span>
              <p className="currency-fixed">
                <strong>{saved.currency}</strong>
              </p>
              <p className="field-hint">
                A saved bill keeps its currency. To use a different one, delete this bill and add it again with the right currency.
              </p>
            </div>
          ) : (
            <CurrencyPicker
              choice={state.currencyChoice}
              custom={state.customCurrency}
              note="Only the symbol shown next to amounts; nothing is converted. Once the bill is saved, its currency can't be changed."
              onChange={(currencyChoice, customCurrency) => {
                setErrors((e) => withoutKey(e, 'currency'));
                change({ ...state, currencyChoice, customCurrency });
              }}
              error={errors.currency}
            />
          )}
          <BillForm
            kind="solo"
            state={state}
            onChange={change}
            errors={errors}
            currency={currency}
            onFieldEdit={(key) => setErrors((e) => clearFieldError(e, key))}
          />
        </form>
        <div className="bill-side">
          <button type="submit" form={formId} className="btn btn-secondary btn-wide">
            Calculate
          </button>
          <Results ref={resultsRef} result={result} currency={currency.trim() || '$'} rates={rateLabels(state)} />
          <div className="save-bar">
            <Alert>{pageError}</Alert>
            <button type="button" className="btn btn-primary btn-wide" onClick={() => void onSave()} disabled={busy}>
              {busy ? 'Saving…' : 'Save bill'}
            </button>
          </div>
        </div>
      </div>
      {guard.dialog}
    </>
  );
}

import { useId, useState } from 'react';

/** "Currency: Rs" with a small info button that explains it's only a symbol. */
export function CurrencyNote({ currency, className }: { currency: string; className?: string }) {
  const [open, setOpen] = useState(false);
  const noteId = useId();
  return (
    <div className={`currency-note ${className ?? ''}`}>
      <p className="muted currency-line">
        Currency: <strong className="currency-symbol">{currency}</strong>
        <button
          type="button"
          className="info-btn"
          aria-expanded={open}
          aria-controls={noteId}
          title="About the currency"
          onClick={() => setOpen((o) => !o)}
        >
          <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
            <circle cx="12" cy="12" r="9.5" fill="none" stroke="currentColor" strokeWidth="1.8" />
            <path d="M12 10.5v6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            <circle cx="12" cy="7.4" r="1.25" fill="currentColor" />
          </svg>
          <span className="visually-hidden">About the currency</span>
        </button>
      </p>
      {open && (
        <div id={noteId} className="info-note">
          <p>
            <strong>{currency}</strong> is only a symbol shown next to amounts. Nothing is converted between currencies.
          </p>
          <p>
            Changing the group's currency in Edit group changes the symbol on every bill in this group. The numbers stay exactly
            the same.
          </p>
        </div>
      )}
    </div>
  );
}

import { forwardRef } from 'react';
import type { CalcResult, RateLabels } from '../billEditor.js';
import { money } from './ui.js';

/** One line of a saved bill: the item, its price and (split by items) who shared it. */
export interface ReceiptItem {
  name: string;
  cents: number | null;
  sharedBy?: string;
}

interface Props {
  result: CalcResult | null;
  currency: string;
  /** Group bills: names by member id, and who paid. */
  names?: Map<string, string>;
  payerId?: string | null;
  /** The rate behind tax, other charges and tip, e.g. "(5%)". */
  rates?: RateLabels;
  /** A saved bill shown read-only: its heading and item lines, and no "results ready" announcement. */
  title?: string;
  items?: ReceiptItem[];
}

/**
 * The receipt. While editing it holds the results ("Press Calculate to see
 * results" until then); a saved bill is shown as the whole receipt, items included.
 */
export const Results = forwardRef<HTMLElement, Props>(function Results({ result, currency, names, payerId, rates, title, items }, ref) {
  const m = (cents: number) => money(cents, currency);
  const editing = title === undefined;
  const headingId = editing ? 'results-heading' : 'receipt-heading';
  return (
    <div className="receipt-wrap">
      <section ref={ref} className="results receipt" aria-labelledby={headingId} tabIndex={editing ? -1 : undefined}>
        <h2 id={headingId} className="section-title">
          {title ?? 'Results'}
        </h2>
        {editing && (
          <div className="visually-hidden" aria-live="polite">
            {result ? `Results ready. Total ${m(result.totals.totalCents)}.` : ''}
          </div>
        )}
        {items && items.length > 0 && (
          <ul className="receipt-items" aria-label="Items">
            {items.map((it, i) => (
              <li key={i} className="receipt-item">
                <div className="receipt-line">
                  <span className="receipt-item-name">{it.name}</span>
                  <span className="receipt-amount">{it.cents === null ? '' : m(it.cents)}</span>
                </div>
                {it.sharedBy && <p className="muted small">Shared by {it.sharedBy}</p>}
              </li>
            ))}
          </ul>
        )}
        {!result ? (
          <p className="muted">Press Calculate to see results</p>
        ) : (
          <>
            <dl className="totals">
              <div>
                <dt>Subtotal</dt>
                <dd>{m(result.totals.itemsCents)}</dd>
              </div>
              <div>
                <dt>
                  Tax{rates?.tax && <span className="rate"> {rates.tax}</span>}
                </dt>
                <dd>{m(result.totals.taxCents)}</dd>
              </div>
              <div>
                <dt>
                  Other charges{rates?.other && <span className="rate"> {rates.other}</span>}
                </dt>
                <dd>{m(result.totals.otherCents)}</dd>
              </div>
              <div>
                <dt>
                  Tip{rates?.tip && <span className="rate"> {rates.tip}</span>}
                </dt>
                <dd>{m(result.totals.tipCents)}</dd>
              </div>
              <div className="totals-grand">
                <dt>Total</dt>
                <dd data-testid="grand-total">{m(result.totals.totalCents)}</dd>
              </div>
            </dl>
            {result.shares && names && (
              <>
                {payerId && (
                  <p className="muted payer-line">
                    {names.get(payerId)} paid {m(result.totals.totalCents)}.
                  </p>
                )}
                <h3 className="subsection-title">Each person&apos;s share</h3>
                <ul className="shares">
                  {result.shares.map((s) => (
                    <li key={s.memberId} className="share" data-testid="share">
                      <div className="share-main">
                        <span className="share-name">{names.get(s.memberId) ?? 'Someone'}</span>
                        <span className="share-amount">{m(s.totalCents)}</span>
                      </div>
                      {s.extraCents > 0 && (
                        <span className="badge">
                          +{s.extraCents} cent{s.extraCents === 1 ? '' : 's'}
                        </span>
                      )}
                      {s.itemsCents !== null && (
                        <p className="share-parts muted">
                          Items {m(s.itemsCents)} · Tax {m(s.taxCents ?? 0)} · Other charges {m(s.otherCents ?? 0)} · Tip {m(s.tipCents ?? 0)}
                        </p>
                      )}
                    </li>
                  ))}
                </ul>
              </>
            )}
          </>
        )}
      </section>
    </div>
  );
});

