export const meta = {
  name: 'rereview-bill-redesign-fixes',
  description: 'Re-review the bill-redesign review fixes (M1-M5, L1-L13) plus new fixes, then adversarially verify findings',
  phases: [
    { title: 'Review', detail: '4 read-only reviewers with different lenses' },
    { title: 'Verify', detail: '2 skeptics per finding try to refute it' },
  ],
}

const ROOT = '/Users/sanaarshad/Desktop/Sana-Arshad-calculator'
const NOTES = '/Users/sanaarshad/Library/Application Support/Claude/side-session-notes/local_f83807d0-85ef-4567-bee8-99aeb5824a52/original-code-review.md'

const RULES = `
Context: a bill-splitting web app (React 19 + react-router 7 client in ${ROOT}/src/client, Express + Postgres server in ${ROOT}/src/server, shared rules in ${ROOT}/src/shared). The bill screens were redesigned (read-only bill views with an "Edit bill" link, edit routes /solo/:id/edit and /groups/:g/bills/:b/edit, item rows with Enter-to-next, people chips with an "Everyone" toggle, a one-box charge field with a "%" / currency-symbol switch, a side column with Calculate, Results and Save, a "Saved" mark on the list after saving, and a CurrencyNote info button). An earlier code review asked for changes; its full text is in the file ${NOTES} — read it.
All changes are uncommitted: \`git -C ${ROOT} diff\` shows them against the last commit (new files: src/client/components/CurrencyNote.tsx, src/tests/unit/billEditor.test.ts, src/tests/e2e/round2-bills.spec.ts).
Since that review, these fixes were made (verify them, do not assume they are right):
- M1: setParticipants no longer rewrites items; item chips get selected={item.sharerIds.filter(onBill)}; toGroupBillInput sends only sharers still on the bill; isBlankItem counts ticked sharers on by-items bills.
- M2/L10: hooks.ts useSavedBill(loaded) copies savedBillId from history state into component state, clears the history state with navigate({pathname, search}, {replace:true, state:null}), and scrolls the saved row (rowRef) into view (block center) once the list has loaded. Used in SoloPages.tsx (SoloListPage) and GroupPage.tsx (BillsTab).
- M3: the charge switch labels focus the box in onClick when e.detail > 0 (no pointerup/setTimeout).
- M4: an @media (forced-colors: active) block for chips and .seg-on in styles.css.
- M5: the amount radio shows <span>{symbol}</span><span class="visually-hidden"> amount</span>, so its name is e.g. "Rs amount".
- L1-L13 as described in the review (hint "Tick who took part first.", addItem edits 'items', full-width item errors via .item-main > .field {display:contents}, empty-line rules + e.repeat + Enter on an empty last line falls through to Calculate, Remove focuses a neighbour row or "+ Add item", keyCode 229 guard, .bill-side max-height + overflow at >=1180px, .alert + .bill-summary margin, people-row auto-fit + nowrap segments, enterKeyHint removed and the hint reworded "With a keyboard, press Enter after a price to start the next item.", docs reworded, more unit tests, CurrencyNote now always renders the note with hidden={!open}).
- Double-save race: hooks.ts useBusy's run(fn) keeps busy=true (button stays disabled) when fn returns 'leaving'; 'leaving' is returned after navigate in 11 places (SoloPages delete+save, GroupBillPages view delete + editor save + settle-up "Payment recorded"/"Payment deleted", GroupsPages create+edit group, GroupPage leave, InvitePage login finish + acceptAsMe finish).
- 360px overflow: overflow-wrap:anywhere added for .back-link, .payer-line, .page-header > div (min-width:0), .alert, .bill-summary, .receipt-item .muted, .member-main > span.
- NEW today: billEditor.ts revealResults() now remembers document.activeElement when Calculate runs and, in its setTimeout, skips scrolling/focusing the results if focus has since moved to another element (not body/null). Reason: a test typed into a field right after Calculate and the delayed focus stole the keystroke.
- NEW today: styles.css adds a global rule "[hidden] { display: none !important; }" because .info-note { display: grid } overrode the hidden attribute, so the closed CurrencyNote was visible.
STRICT LIMITS: you are read-only. Do NOT edit files. Do NOT run Playwright, \`npm test\`, \`npm run test:api\`, \`npm run test:e2e\`, any server, or anything touching databases — a browser test suite is running on port 3100 right now. You MAY run \`npx tsc --noEmit -p tsconfig.json\`, \`npx eslint client\` and \`npx vitest run --project unit\` from ${ROOT}/src, plus git diff / grep / reading files.
Report only real, concrete problems with a user-visible or correctness impact (or a fix that was claimed but not actually done). Each finding needs file:line, a concrete scenario (inputs/steps -> wrong outcome), and a minimal fix. No style nits. If nothing is wrong in your area, return an empty list.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          severity: { type: 'string', enum: ['HIGH', 'MEDIUM', 'LOW'] },
          file: { type: 'string' },
          line: { type: 'number' },
          scenario: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['title', 'severity', 'file', 'scenario', 'fix'],
      },
    },
    statuses: {
      type: 'array',
      description: 'Only for the fix-check reviewer: one entry per original item M1-M5, L1-L13',
      items: {
        type: 'object',
        properties: { item: { type: 'string' }, status: { type: 'string', enum: ['fixed', 'partly fixed', 'not fixed', 'no longer applies'] }, evidence: { type: 'string' } },
        required: ['item', 'status', 'evidence'],
      },
    },
    summary: { type: 'string' },
  },
  required: ['findings', 'summary'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean', description: 'true only if the problem is real and reproducible from the code as it is now' },
    severity: { type: 'string', enum: ['HIGH', 'MEDIUM', 'LOW', 'NONE'] },
    reasoning: { type: 'string' },
  },
  required: ['real', 'severity', 'reasoning'],
}

const REVIEWERS = [
  {
    key: 'fix-check',
    agentType: 'oh-my-claudecode:code-reviewer',
    prompt: `${RULES}\n\nYOUR LENS: you are re-reviewing your own earlier review. For EACH item M1-M5 and L1-L13 in ${NOTES}, check the current code and record a status (fixed / partly fixed / not fixed / no longer applies) with file:line evidence in "statuses". Any item that is not fully and correctly fixed, or whose fix introduced a new problem, also goes in "findings". Also check the two NEW changes (revealResults focus guard, global [hidden] rule) and the double-save 'leaving' fix at all 11 sites. Finish with an overall verdict (APPROVE or REQUEST CHANGES) in "summary".`,
  },
  {
    key: 'logic',
    prompt: `${RULES}\n\nYOUR LENS: fresh correctness review of the logic, hunting regressions introduced by the fixes. Focus on src/client/components/BillForm.tsx, src/client/billEditor.ts, src/client/hooks.ts and the pages that call useBusy/useSavedBill/revealResults (SoloPages.tsx, GroupBillPages.tsx, GroupPage.tsx, GroupsPages.tsx, InvitePage.tsx). Think about: a 'leaving' return when navigation does not actually leave (same path, blocked by the unsaved-changes guard, navigate throwing, component staying mounted) leaving a button disabled forever; useSavedBill clearing history state then re-marking or scroll loops; empty-line/sharer filtering mismatches between what is calculated, what is sent to the server and how server errors are mapped back (toFormErrors); Enter-key handling edge cases; revealResults guard edge cases (Safari where buttons do not take focus on click, Enter-submit from a field, results already focused).`,
  },
  {
    key: 'css-a11y',
    prompt: `${RULES}\n\nYOUR LENS: CSS and accessibility of the changes in src/client/styles.css, BillForm.tsx, CurrencyNote.tsx, Results.tsx. Check: the new global "[hidden] { display: none !important; }" against every element that might rely on the hidden attribute or on display being set elsewhere (search the client for hidden attributes, <dialog>, details/summary, etc.); overflow-wrap/min-width rules actually covering all long-name places at 360px (group, bill, item and member names: back links, headings, summaries, receipts, chips, alerts, member rows, activity rows); the forced-colors block; .bill-side max-height/overflow clipping focus outlines; .item-main > .field {display: contents} keeping labels/errors associated; label-in-name and accessible names on the charge switch and chips; dark mode tokens for any new colours.`,
  },
  {
    key: 'docs',
    prompt: `${RULES}\n\nYOUR LENS: docs vs app. In ${ROOT}/docs/user-stories.md, read US-05 (#16, #17), US-06 #7, US-07, US-08, US-13 #11/#12, US-14 (#8-#12), US-18 (#2, #3, #5), US-20 #6, US-25 (#1, #14), US-26 (#5, #6, #9, #10, #11), US-34 #3, US-36 #1, US-37 #3, US-39 #5, and check each Given/When/Then against what the code actually does today (exact wording of messages and hints where the doc quotes them). The rule for this project: every story marked Implemented must work exactly as its acceptance criteria describe. Report each mismatch as a finding with the doc line, the code line, and which side should change (prefer changing the doc when the app behaviour is the better one).`,
  },
]

phase('Review')
const results = await pipeline(
  REVIEWERS,
  (r) => agent(r.prompt, { label: `review:${r.key}`, phase: 'Review', schema: FINDINGS, agentType: r.agentType }),
  (review, r) => {
    if (!review) return { reviewer: r.key, review: null, verified: [] }
    return parallel(review.findings.map((f) => () =>
      parallel(['correctness: read the exact code paths and decide whether the scenario really happens as described', 'user impact: decide whether a real user (or the project rule that Implemented stories must match their acceptance criteria exactly) is affected, and whether existing code or tests already prevent it'].map((lens, i) => () =>
