const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          severity: { type: 'string', enum: ['HIGH', 'MEDIUM', 'LOW'] },
          file: { type: 'string' },
          line: { type: 'number' },
          scenario: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['title', 'severity', 'file', 'scenario', 'fix'],
      },
    },
    statuses: {
      type: 'array',
      description: 'Only for the fix-check reviewer: one entry per original item M1-M5, L1-L13',
      items: {
        type: 'object',
        properties: { item: { type: 'string' }, status: { type: 'string', enum: ['fixed', 'partly fixed', 'not fixed', 'no longer applies'] }, evidence: { type: 'string' } },
        required: ['item', 'status', 'evidence'],
      },
    },
    summary: { type: 'string' },
  },
  required: ['findings', 'summary'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean', description: 'true only if the problem is real and reproducible from the code as it is now' },
    severity: { type: 'string', enum: ['HIGH', 'MEDIUM', 'LOW', 'NONE'] },
    reasoning: { type: 'string' },
  },
  required: ['real', 'severity', 'reasoning'],
}

const REVIEWERS = [
  {
    key: 'fix-check',
    agentType: 'oh-my-claudecode:code-reviewer',
    prompt: `${RULES}\n\nYOUR LENS: you are re-reviewing your own earlier review. For EACH item M1-M5 and L1-L13 in ${NOTES}, check the current code and record a status (fixed / partly fixed / not fixed / no longer applies) with file:line evidence in "statuses". Any item that is not fully and correctly fixed, or whose fix introduced a new problem, also goes in "findings". Also check the two NEW changes (revealResults focus guard, global [hidden] rule) and the double-save 'leaving' fix at all 11 sites. Finish with an overall verdict (APPROVE or REQUEST CHANGES) in "summary".`,
