/**
 * After saving a bill, its list is opened with the bill's id: the list marks that
 * row "Saved" and scrolls it into view once loaded. The id is then cleared from
 * history, so going back to the list or reloading doesn't mark it again.
 */
export function useSavedBill(loaded: boolean): { savedId: string | undefined; rowRef: RefObject<HTMLAnchorElement | null> } {
  const location = useLocation();
  const navigate = useNavigate();
  const [savedId] = useState(() => (location.state as { savedBillId?: string } | null)?.savedBillId);
  const rowRef = useRef<HTMLAnchorElement>(null);
  useEffect(() => {
    if (savedId) navigate({ pathname: location.pathname, search: location.search }, { replace: true, state: null });
    // Once, on arrival.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => {
    if (loaded && savedId) rowRef.current?.scrollIntoView({ block: 'center', behavior: scrollBehavior() });
  }, [loaded, savedId]);
  return { savedId, rowRef };
}

