export const meta = {
  name: 'review-round2-followup-fixes',
  description: 'Review the follow-up fixes (Back after save, Enter rule, symbol cap, badge space, dialog wrap) and verify findings',
  phases: [
    { title: 'Review', detail: '2 read-only reviewers' },
    { title: 'Verify', detail: '2 skeptics per finding' },
  ],
}

const ROOT = '/Users/sanaarshad/Desktop/Sana-Arshad-calculator'
const RULES = `
A bill-splitting web app: React 19 + react-router 7 (data router, createBrowserRouter) client in ${ROOT}/src/client. All work is uncommitted (\`git -C ${ROOT} diff\`). Review ONLY these follow-up changes made today:
1. src/client/hooks.ts: new FROM_LIST constant, a module-level \`justSaved\` slot, new useShowSavedBill() and a changed useSavedBill(). The list pages' "New solo bill" / "Add bill" links (SoloPages.tsx SoloListPage incl. its EmptyState, GroupPage.tsx header link and Bills-tab EmptyState) pass state={FROM_LIST}. On save, SoloBillEditor (SoloPages.tsx) and GroupBillEditor (GroupBillPages.tsx) call showSaved(listPath, id): if the editor's location.state.fromList is set it stores {path,id,at} in justSaved and calls navigate(-1); otherwise navigate(listPath, {replace:true, state:{savedBillId}}). useSavedBill reads savedBillId from history state, or justSaved when its path matches and it is < 10 s old; its mount effect clears justSaved and clears history state. ui.tsx EmptyState gained an optional action.state. The goal: after saving a NEW bill opened from its list, Back must not show the same list a second time, and the list still marks the bill "Saved" and scrolls to it.
2. BillForm.tsx onItemKey: Enter on the last line falls through to the form submit (Calculate) only when isBlankItem(state, item) (exported from billEditor.ts) — so a by-items line with people ticked but no name/price now moves to its price instead.
3. styles.css: .seg input gets width/height 100%; new .seg-symbol (inline-block, max-width 4em, ellipsis) on the currency symbol span in the charge switch; .dialog-title and .callout-title get overflow-wrap:anywhere; .link-row .badge-saved margin-left 8px→4px plus a {' '} text node before the "Saved" badge in both lists.
4. billEditor.ts revealResults: skips focusing/scrolling the results if focus moved to another element after Calculate.
Think hard about edge cases: StrictMode double effects/initialisers (check src/client/main.tsx), the unsaved-changes guard (src/client/components/UnsavedGuard.tsx, useBlocker) and navigate(-1) (POP) — is the POP blocked?; useBusy 'leaving' with a POP navigation; the list page being remounted vs reused; history entries when the editor page was reloaded, opened in a new tab, or reached via browser Back/Forward; the Dashboard / group-chooser entry points (no FROM_LIST); edit flows; ScrollRestoration; whether the "Saved" mark can wrongly appear later; the 4em cap cutting valid 3-character symbols (e.g. "PKR", "CHF", "AED", "SAR", "R$", "WWW") in the app's fonts; screen-reader names.
STRICT LIMITS: read-only. Do NOT edit files. Do NOT run Playwright, npm test, test:api, test:e2e, any server or anything touching databases — the full test suite is running right now. You MAY run \`npx tsc --noEmit -p tsconfig.json\`, \`npx eslint client\` and \`npx vitest run --project unit\` from ${ROOT}/src, and read files / git diff.
Report only real, concrete problems with a user-visible or correctness impact, each with file:line, a concrete scenario and a minimal fix. Return an empty list if none.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: { type: 'array', items: { type: 'object', properties: {
      title: { type: 'string' }, severity: { type: 'string', enum: ['HIGH', 'MEDIUM', 'LOW'] }, file: { type: 'string' }, line: { type: 'number' }, scenario: { type: 'string' }, fix: { type: 'string' } },
      required: ['title', 'severity', 'file', 'scenario', 'fix'] } },
    summary: { type: 'string' },
  },
  required: ['findings', 'summary'],
}
const VERDICT = { type: 'object', properties: { real: { type: 'boolean' }, severity: { type: 'string', enum: ['HIGH', 'MEDIUM', 'LOW', 'NONE'] }, reasoning: { type: 'string' } }, required: ['real', 'severity', 'reasoning'] }

const REVIEWERS = [
  { key: 'navigation', agentType: 'oh-my-claudecode:code-reviewer', prompt: `${RULES}\n\nYOUR LENS: changes 1 and 4 — navigation/history correctness of the Back-after-save fix and the revealResults guard. Trace react-router 7's navigate(-1), useBlocker and the Layout's focus/scroll behaviour in the actual source under ${ROOT}/src/node_modules/react-router if needed.` },
  { key: 'form-css', prompt: `${RULES}\n\nYOUR LENS: changes 2 and 3 — the Enter rule and the CSS/accessibility changes. Check the symbol cap against real glyph widths of the app's font (see the @font-face / font-family in styles.css and index.html), the radio now sized 100% inside every .seg (tip-on switch, split switch, invite switches too), and the name/badge spacing.` },
]

phase('Review')
const results = await pipeline(
  REVIEWERS,
  (r) => agent(r.prompt, { label: `review:${r.key}`, phase: 'Review', schema: FINDINGS, agentType: r.agentType }),
  (review, r) => {
    if (!review) return { reviewer: r.key, review: null, verified: [] }
    return parallel(review.findings.map((f) => () =>
      parallel(['correctness: read the exact code paths (and library source if needed) and decide whether the scenario really happens', 'user impact: decide whether a real user is affected, and whether existing code already prevents it'].map((lens, i) => () =>
        agent(`${RULES}\n\nA reviewer reported this finding. Try to REFUTE it with this lens — ${lens}. Default to real=false if evidence is weak.\n\nFINDING (${f.severity}) ${f.title}\nFile: ${f.file}:${f.line ?? ''}\nScenario: ${f.scenario}\nProposed fix: ${f.fix}`, { label: `verify:${r.key}:${i}`, phase: 'Verify', schema: VERDICT })))
        .then((votes) => ({ ...f, reviewer: r.key, votes: votes.filter(Boolean) }))))
      .then((verified) => ({ reviewer: r.key, review, verified: verified.filter(Boolean) }))
  },
)
const out = results.filter(Boolean)
const confirmed = [], refuted = []
for (const r of out) for (const f of r.verified) {
  const yes = f.votes.filter((v) => v.real).length
  if (yes >= 1) confirmed.push({ ...f, confirmations: `${yes}/${f.votes.length}` })
  else refuted.push({ title: f.title, reviewer: f.reviewer, why: f.votes.map((v) => v.reasoning).join(' | ') })
}
log(`${confirmed.length} confirmed, ${refuted.length} refuted`)
return { summaries: out.map((r) => ({ reviewer: r.reviewer, summary: r.review?.summary ?? 'reviewer failed' })), confirmed, refuted }

